const SLOTS=['07:30','08:30','09:45','10:45','11:45'],SLOTE=['08:30','09:30','10:45','11:45','12:45'];
const WD=['Lundi','Mardi','Mercredi','Jeudi','Vendredi'];
const HOLI=[['2026-04-04','2026-04-19'],['2026-07-03','2026-08-31'],['2026-12-19','2027-01-03']];
const isSchoolDay=d=>{const w=pd(d).getDay();return w>=1&&w<=5&&!HOLI.some(([a,b])=>d>=a&&d<=b)};
const nextSchoolDay=d=>{for(let i=0;i<40&&!isSchoolDay(d);i++)d=addDays(d,1);return d};
function lastSchoolDays(end,n){const o=[];let d=end;for(let i=0;i<150&&o.length<n;i++){if(isSchoolDay(d)&&d>='2026-09-01')o.push(d);d=addDays(d,-1)}return o}
const clsById=id=>S.classes.find(c=>c.id===id);
const stuOfClass=cid=>students().filter(s=>s.level===cid).sort((a,b)=>a.nom.localeCompare(b.nom)||a.prenom.localeCompare(b.prenom));
const subjOf=cid=>{const c=clsById(cid);return c?S.subjects.filter(s=>s.cycles.includes(c.cycle)):[]};
const graded=cid=>(clsById(cid)||{}).cycle!=='Maternelle';
const subj=id=>S.subjects.find(s=>s.id===id)||{name:'—',color:'#94a3b8',short:'—'};
const teacherOf=(cid,sid)=>emp((S.assign[cid]||{})[sid]);
const tName=e=>e?e.prenom+' '+e.nom:'—';
const TEACHER_ID=()=>S.persona.teacher;
const myClasses=()=>{const t=TEACHER_ID();return S.classes.filter(c=>c.teacherId===t||Object.values(S.assign[c.id]||{}).includes(t))};
const kids=()=>S.persona.children.map(id=>client(id)).filter(x=>x&&x.id);
function curKid(){const ids=S.persona.children;if(!ids.includes(ui.child))ui.child=ids[0];return client(ui.child)}
function setChild(id){ui.child=id;render()}
function kidSwitch(){const k=curKid();return `<div class="kid-switch mb">${kids().map(c=>`<button class="${c.id===k.id?'active':''}" onclick="setChild('${c.id}')">${avatar(c.name,30)}<span><b>${esc(c.prenom)}</b><small>${esc(c.classe)}</small></span></button>`).join('')}</div>`}

/* ---------- moyennes ---------- */
function evalsOf(cid,sid){return cached('ev|'+cid+'|'+sid,()=>S.evaluations.filter(e=>e.classId===cid&&e.subjectId===sid).sort((a,b)=>a.date.localeCompare(b.date)))}
function subjAvg(st,sid){return cached('sa|'+st.id+'|'+sid,()=>{let t=0,c=0;for(const e of evalsOf(st.level,sid)){const g=e.grades[st.id];if(g==null||g==='')continue;t+=g/e.max*20*e.coef;c+=e.coef}return c?t/c:null})}
function genAvg(st){return cached('ga|'+st.id,()=>{let t=0,c=0;for(const s of subjOf(st.level)){const a=subjAvg(st,s.id);if(a==null)continue;t+=a*s.coef;c+=s.coef}return c?t/c:null})}
const avgOf=a=>{const v=a.filter(x=>x!=null);return v.length?sum(v)/v.length:null};
const classSubjAvg=(cid,sid)=>cached('csa|'+cid+'|'+sid,()=>avgOf(stuOfClass(cid).map(s=>subjAvg(s,sid))));
const classGenAvg=cid=>cached('cga|'+cid,()=>avgOf(stuOfClass(cid).map(genAvg)));
function rankOf(st){const l=stuOfClass(st.level).map(s=>({id:s.id,a:genAvg(s)})).filter(x=>x.a!=null).sort((a,b)=>b.a-a.a);const i=l.findIndex(x=>x.id===st.id);return i<0?null:[i+1,l.length]}
const fa=a=>a==null||isNaN(a)?'—':a.toFixed(2).replace('.',',');
const avgCell=a=>`<span class="avg ${a==null?'':a<10?'low':a>=14?'high':''}">${fa(a)}</span>`;
function autoAppr(a){if(a==null)return'—';if(a>=16)return'Excellent travail, félicitations.';if(a>=14)return'Très bon trimestre, continuez ainsi.';if(a>=12)return'Bon travail, des efforts réguliers.';if(a>=10)return'Résultats corrects, peut mieux faire.';if(a>=8)return'Résultats fragiles, il faut s’investir davantage.';return'Trimestre difficile, travail insuffisant.'}
function mention(a){return a==null?'':a>=16?'Félicitations':a>=14?'Tableau d’honneur':a>=12?'Encouragements':a<8?'Avertissement travail':''}
/* ---------- présences ---------- */
function attIdx(){return cached('ai',()=>{const m={};for(const a of S.attendance)(m[a.studentId]=m[a.studentId]||[]).push(a);return m})}
const attOf=id=>(attIdx()[id]||[]).slice().sort((a,b)=>b.date.localeCompare(a.date));
function presenceRate(sts,days){const set=new Set(sts.map(s=>s.id)),ds=new Set(days);const ab=S.attendance.filter(a=>a.status==='absent'&&ds.has(a.date)&&set.has(a.studentId)).length;const tot=sts.length*days.length;return tot?1-ab/tot:1}

/* ================= DONNÉES DE DÉMONSTRATION ================= */
function seedEdu(R,ri,pick){const cc=S.country;const sec=cc==='CD'?'Secondaire':'Collège';const P=['Primaire',sec];
 S.subjects=[{id:'fr',name:'Français',short:'FRA',coef:4,hours:6,color:'#1f52e5',cycles:P},{id:'ma',name:'Mathématiques',short:'MAT',coef:4,hours:6,color:'#0ea5e9',cycles:P},{id:'an',name:'Anglais',short:'ANG',coef:2,hours:2,color:'#ec4899',cycles:P},{id:'hg',name:'Histoire-Géographie',short:'HG',coef:2,hours:2,color:'#f59e0b',cycles:P},{id:'sc',name:cc==='CD'?'Sciences – Biologie':'Sciences (SVT)',short:'SCI',coef:2,hours:3,color:'#10b981',cycles:P},{id:'pc',name:'Physique-Chimie',short:'PC',coef:2,hours:2,color:'#8b5cf6',cycles:[sec]},{id:'ec',name:'Éducation civique et morale',short:'ECM',coef:1,hours:1,color:'#64748b',cycles:P},{id:'ep',name:'Éducation physique',short:'EPS',coef:1,hours:2,color:'#ef4444',cycles:P},{id:'ev',name:'Éveil et langage',short:'ÉVE',coef:1,hours:8,color:'#f97316',cycles:['Maternelle']},{id:'gr',name:'Graphisme et dessin',short:'GRA',coef:1,hours:5,color:'#a855f7',cycles:['Maternelle']},{id:'mo',name:'Motricité et jeux',short:'MOT',coef:1,hours:5,color:'#14b8a6',cycles:['Maternelle']}];
 const mat=['em5','em6','em5'],prim=['em7','em8','em9','em10','em11','em12'],secT=['em13','em14','em15','em13'];let im=0,ip=0,is=0;
 S.classes=S.fees.map((l,i)=>{const t=l.cycle==='Maternelle'?mat[im++%3]:l.cycle==='Primaire'?prim[ip++%6]:secT[is++%4];return{id:l.id,name:l.name,cycle:l.cycle,room:'Salle '+(i+1),capacity:l.cycle==='Maternelle'?25:30,teacherId:t}});
 S.assign={};for(const c of S.classes){S.assign[c.id]={};for(const s of subjOf(c.id)){let t=c.teacherId;if(c.cycle===sec)t={fr:'em13',ma:'em14',an:'em15',sc:'em16',pc:'em17',ep:'em18',hg:'em13',ec:'em15'}[s.id];else if(c.cycle==='Primaire'){if(s.id==='an')t='em15';if(s.id==='ep')t='em18'}S.assign[c.id][s.id]=t}}
 // emploi du temps
 S.timetable={};const busy={};for(const c of S.classes){const free=[];for(let d=1;d<=5;d++)for(let s=0;s<5;s++)free.push(d+'-'+s);for(let i=free.length-1;i>0;i--){const j=Math.floor(R()*(i+1));[free[i],free[j]]=[free[j],free[i]]}const L=[];const order=subjOf(c.id).slice().sort((a,b)=>(['an','ep','pc','sc'].includes(b.id)?1:0)-(['an','ep','pc','sc'].includes(a.id)?1:0));
  for(const s of order)for(let h=0;h<s.hours&&free.length;h++){const t=S.assign[c.id][s.id];let ix=free.findIndex(k=>!(busy[t]||new Set()).has(k)&&L.filter(l=>l.sub===s.id&&l.d===+k[0]).length<(s.hours>=5?2:1));if(ix<0)ix=free.findIndex(k=>!(busy[t]||new Set()).has(k));if(ix<0)ix=0;const k=free.splice(ix,1)[0];(busy[t]=busy[t]||new Set()).add(k);L.push({d:+k[0],s:+k[2],sub:s.id,t,room:s.id==='ep'?'Terrain':c.room})}S.timetable[c.id]=L}
 // évaluations du 1er trimestre
 const days=[];for(let d='2026-09-14';d<=addDays(TODAY,-2)&&d<='2026-12-18';d=addDays(d,1))if(isSchoolDay(d))days.push(d);
 const TT={fr:['Dictée','Rédaction','Grammaire','Lecture'],ma:['Calcul','Géométrie','Problèmes','Fractions'],an:['Vocabulaire','Oral'],hg:['Contrôle de cours','Cartographie'],sc:['Le corps humain','Les végétaux'],pc:['La matière','Électricité'],ec:['Exposé','Contrôle'],ep:['Endurance','Sports collectifs']};
 const ab={};students().forEach(s=>ab[s.id]=7.5+R()*10);S.evaluations=[];let ne=0;
 if(days.length)for(const c of S.classes){if(!graded(c.id))continue;for(const s of subjOf(c.id)){const k=s.coef>=4?3:2;const off=(R()-.5)*2.5;for(let i=0;i<k;i++){const date=days[Math.min(days.length-1,Math.floor((i+R()*.8)/k*days.length))];const g={};for(const st of stuOfClass(c.id)){if(R()<.03)continue;let v=ab[st.id]+off+(R()-.5)*6+(s.id==='ep'?1.5:0);g[st.id]=Math.max(2,Math.min(20,Math.round(v*2)/2))}ne++;S.evaluations.push({id:'ev'+ne,classId:c.id,subjectId:s.id,title:TT[s.id][i%TT[s.id].length],date,max:20,coef:i===k-1?2:1,term:1,grades:g})}}}
 // présences
 S.attendance=[];S.appelDone={};let na=0;const MOT=['Maladie','Rendez-vous médical','Raison familiale','Transport'];
 for(let d='2026-09-01';d<=TODAY;d=addDays(d,1)){if(!isSchoolDay(d))continue;for(const c of S.classes){if(d===TODAY&&R()<.45)continue;S.appelDone[d+'|'+c.id]=true;for(const st of stuOfClass(c.id)){const r=R();if(r<.024){const j=R()<.65;na++;S.attendance.push({id:'at'+na,date:d,studentId:st.id,status:'absent',justified:j,motif:j?pick(MOT):''})}else if(r<.04){na++;S.attendance.push({id:'at'+na,date:d,studentId:st.id,status:'retard',minutes:ri(5,25),justified:R()<.3,motif:''})}}}}
 // famille de démonstration (espace parent)
 const best=cid=>stuOfClass(cid).slice().sort((a,b)=>ab[b.id]-ab[a.id]);const k1=best(S.classes[6].id)[3],k2=best(S.classes[10].id)[5];const fam=k1.nom;k2.nom=fam;k2.name=k2.prenom+' '+fam.toUpperCase();k2.parent={...k1.parent};S.persona={teacher:'em14',children:[k1.id,k2.id]};
 // inscriptions 2027-2028 et réinscriptions
 const NM=NAMES[cc]||NAMES.default;const ph=()=>S.company.phone.replace(/\d{2} ?\d{2}$/,pad(ri(10,99))+' '+pad(ri(10,99)));
 const IST=['nouvelle','nouvelle','nouvelle','en_cours','en_cours','en_cours','validee','validee','refusee'];
 S.inscriptions=IST.map((st,i)=>{const sx=R()<.5?'F':'M';const nom=pick(NM.n);return{id:'in'+(i+1),prenom:pick(sx==='F'?NM.f:NM.m),nom,sexe:sx,level:pick(S.fees).id,annee:i===3?S.schoolYear:'2027-2028',statut:st,date:addDays(TODAY,-ri(1,40)),source:pick(['Site web','Portes ouvertes','Recommandation','Téléphone']),parent:{name:(R()<.6?'Mme ':'M. ')+pick(R()<.6?NM.pf:NM.pm)+' '+nom,phone:ph()},docs:{acte:R()<.8,photo:R()<.6,bulletin:R()<.5,domicile:R()<.4},note:st==='refusee'?'Classe complète':''}}).sort((a,b)=>b.date.localeCompare(a.date));
 S.reinsc={};for(const s of students()){const r=R();S.reinsc[s.id]=r<.48?'oui':r<.52?'non':'attente'}
 // communication
 const T=(n,h)=>addDays(TODAY,-n)+' '+h;const pk=i=>students()[Math.floor(students().length*i)];
 S.threads=[{id:'th1',studentId:k1.id,with:'admin',subject:'Échéancier de la 2e tranche',unread:{staff:true,parent:false},messages:[{from:'parent',text:'Bonjour, serait-il possible de payer la 2e tranche en deux fois (décembre et janvier) ? Merci.',date:T(0,'08:12')}]},
  {id:'th2',studentId:k2.id,with:'em14',subject:'Devoir de mathématiques',unread:{staff:false,parent:true},messages:[{from:'parent',text:'Bonjour Monsieur, '+k2.prenom+' a eu des difficultés sur les fractions. Pourriez-vous lui donner des exercices supplémentaires ?',date:T(4,'19:05')},{from:'staff',text:'Bonjour, bien sûr. Je lui remettrai une fiche d’entraînement demain. Il est sérieux, il va progresser.',date:T(3,'12:15')}]},
  {id:'th3',studentId:pk(.82).id,with:'em14',subject:'Absence de mardi',unread:{staff:true,parent:false},messages:[{from:'parent',text:'Bonjour, mon enfant était malade mardi. Pourriez-vous lui indiquer les exercices à rattraper ? Cordialement.',date:T(1,'07:48')}]},
  {id:'th4',studentId:pk(.4).id,with:'admin',subject:'Changement de numéro de téléphone',unread:{staff:true,parent:false},messages:[{from:'parent',text:'Bonjour, merci de mettre à jour mon numéro : '+ph()+'.',date:T(2,'18:30')}]},
  {id:'th5',studentId:pk(.25).id,with:'admin',subject:'Reçu de paiement',unread:{staff:false,parent:false},messages:[{from:'parent',text:'Bonjour, pouvez-vous me renvoyer le reçu de la 1re tranche ?',date:T(9,'10:02')},{from:'staff',text:'Bonjour, le reçu vient de vous être envoyé sur WhatsApp. Bonne journée.',date:T(8,'09:20')}]}];
 S.announcements=[{id:'an1',title:'Réunion parents-professeurs',body:'Les rencontres parents-professeurs du 1er trimestre auront lieu le jeudi 3 décembre de 14 h à 17 h. Présence vivement souhaitée.',audience:'parents',date:addDays(TODAY,-1),author:S.company.director,pinned:true},{id:'an2',title:'Conseils de classe du 1er trimestre',body:'Les conseils de classe se tiendront du 14 au 17 décembre. Merci de saisir toutes les notes avant le 11 décembre.',audience:'enseignants',date:addDays(TODAY,-3),author:S.company.director,pinned:false},{id:'an3',title:'Rappel : 2e tranche des frais',body:'La 2e tranche est payable du 5 novembre au 5 février, à la caisse, par Mobile Money ou par virement sur le compte Equity Bank RDC de l’école. Merci de conserver vos reçus.',audience:'parents',date:addDays(TODAY,-6),author:'Économat',pinned:false},{id:'an4',title:'Journée sportive',body:'La journée sportive inter-classes aura lieu le vendredi 27 novembre. Tenue de sport obligatoire.',audience:'tous',date:addDays(TODAY,-9),author:S.company.director,pinned:false}];
 S.events=[['2026-09-01','Rentrée scolaire','vie'],['2026-11-20','Photo de classe','vie'],['2026-11-27','Journée sportive','vie'],['2026-12-03','Réunion parents-professeurs','reunion'],['2026-12-11','Date limite de saisie des notes','examen'],['2026-12-14','Conseils de classe (primaire)','conseil'],['2026-12-16','Conseils de classe (secondaire)','conseil'],['2026-12-18','Fête de fin d’année','vie'],['2026-12-19','Début des congés de Noël','vacances'],['2027-01-04','Reprise des cours','vie'],['2027-02-05','Échéance 2e tranche · ouverture de la 3e','finance'],['2027-04-05','Échéance 3e tranche','finance']].map((e,i)=>({id:'ve'+(i+1),date:e[0],title:e[1],type:e[2]}));
 S.appr={};S.published={};S.docLog=[];S.notifications=[]}

/* ================= RÔLES ================= */
const NAVS={
 admin:[[null,[['dashboard','Tableau de bord','home'],['rapports','Rapports','chart']]],['Scolarité',[['eleves','Élèves & familles','users'],['inscriptions','Inscriptions','plus'],['classes','Classes & niveaux','layers'],['matieres','Matières','book'],['edt','Emploi du temps','calendar']]],['Vie scolaire',[['presences','Présences','checkCircle'],['notes','Notes & évaluations','edit'],['bulletins','Bulletins','file']]],['Relation familles',[['communication','Communication','send'],['documents','Documents','copy']]],['Finances',[['scolarite','Frais de scolarité','receipt'],['recouvrement','Recouvrement','alert'],['achats','Dépenses','cart'],['tresorerie','Caisse & trésorerie','wallet'],['compta','Comptabilité','book'],['etats','États financiers','pie']]],['Personnel',[['salaries','Personnel','briefcase'],['paie','Paie','payslip'],['conges','Congés & absences','calendar'],['declarations','Déclarations sociales','shield']]],['Administration',[['tiers','Fournisseurs','cart'],['parametres','Paramètres','settings']]]],
 teacher:[[null,[['dashboard','Accueil','home']]],['Enseignement',[['classes','Mes classes','layers'],['edt','Emploi du temps','calendar'],['presences','Appel','checkCircle'],['notes','Notes & évaluations','edit'],['bulletins','Bulletins','file']]],['Familles',[['communication','Communication','send']]]],
 parent:[[null,[['dashboard','Accueil','home']]],['Mes enfants',[['notes','Notes & bulletins','edit'],['presences','Absences & retards','checkCircle'],['edt','Emploi du temps','calendar'],['paiements','Paiements','wallet'],['documents','Documents','copy']]],['Échanges',[['communication','Communication','send']]]]};
const ROLE_LBL={admin:'Administration',teacher:'Espace enseignant',parent:'Espace parent'};
function setRole(r){ui.role=r;ui.page='dashboard';ui.params={};ui.tab={};ui.f={};ui.appel=null;closeModal();render();window.scrollTo(0,0)}
function persona(){if(ui.role==='teacher'){const e=emp(TEACHER_ID());return{n:e.prenom+' '+e.nom,s:e.poste.replace(/\(.*\)/,'').trim(),i:e.prenom[0]+e.nom[0]}}if(ui.role==='parent'){const p=curKid().parent;return{n:p.name.replace(/^(Mme|M\.)\s+/,''),s:'Parent · '+kids().length+' enfants',i:p.name.replace(/^(Mme|M\.)\s+/,'').split(' ').map(w=>w[0]).join('').slice(0,2)}}const e=S.employees[2]||{prenom:'A',nom:'',poste:'admin'};return{n:e.prenom+' '+e.nom,s:e.poste.split('–')[0].trim(),i:e.prenom[0]+(e.nom[0]||'')}}
function threadsFor(r){r=r||ui.role;if(r==='admin')return S.threads.filter(t=>t.with==='admin');if(r==='teacher')return S.threads.filter(t=>t.with===TEACHER_ID());return S.threads.filter(t=>S.persona.children.includes(t.studentId))}
const isUnread=t=>ui.role==='parent'?t.unread.parent:t.unread.staff;
function navCount(id){if(id==='tresorerie'&&ui.role==='admin')return S.txs.filter(t=>!t.match&&!t.acc).length;if(id==='recouvrement')return lateStudents().length;if(id==='conges')return S.leaves.filter(l=>l.status==='pending').length;if(id==='communication')return threadsFor().filter(isUnread).length;if(id==='inscriptions')return S.inscriptions.filter(i=>i.statut==='nouvelle').length;if(id==='paiements')return kids().filter(k=>stuBal(k).late>0.5).length;return 0}
function sidebar(){const p=persona();const nav=NAVS[ui.role];return `<aside class="sidebar ${ui.sidebarOpen?'open':''}"><div class="brand"><div class="logo-sq">L${SPARK}</div><div class="brand-name">Light Academy</div></div>
 <div class="org-card" onclick="${ui.role==='admin'?"go('parametres')":''}"><div class="org-ini">${orgIni()}</div><div class="min0 grow"><div class="fw6 ellipsis">${esc(S.company.name)}</div><div class="sm muted">${ui.role==='admin'?students().length+' élèves · '+S.currency:ROLE_LBL[ui.role]}</div></div>${ic('chevronRight',16)}</div>
 <nav class="nav">${nav.map(([sec,items])=>`${sec?`<div class="nav-section">${sec}</div>`:''}${items.map(([id,label,icon])=>{const c=navCount(id);return `<a class="${ui.page===id?'active':''}" onclick="go('${id}')">${ic(icon,18)}<span>${label}</span>${c?`<span class="count">${c}</span>`:''}</a>`}).join('')}`).join('')}</nav>
 <div class="sidebar-foot"><div class="me-row"><div class="me-av">${esc(p.i)}</div><div class="min0"><div class="fw6 ellipsis">${esc(p.n)}</div><div class="sm muted ellipsis">${esc(p.s)}</div></div></div><div class="role-sw">${[['admin','Admin'],['teacher','Enseignant'],['parent','Parent']].map(([k,l])=>`<button class="${ui.role===k?'active':''}" onclick="setRole('${k}')">${l}</button>`).join('')}</div></div></aside>`}
function topbar(){const p=persona();return `<header class="topbar"><button class="icon-btn menu-btn" onclick="toggleSidebar(true)" aria-label="Menu">${ic('menu')}</button><div class="top-search input-ic">${ic('search',18)}<input id="gs" class="input" placeholder="${ui.role==='parent'?'Rechercher…':'Rechercher un élève, une facture, un reçu…'}" autocomplete="off" oninput="gsearch(this.value)" onfocus="gsearch(this.value)" onblur="setTimeout(()=>{const r=document.getElementById('gs-res');r&&r.classList.remove('show')},180)"><span class="kbd">/</span><div id="gs-res" class="search-res"></div></div><div class="topbar-right"><span class="pill hide-sm">Année ${S.schoolYear}</span><button class="top-ic" title="Annonces" onclick="go('communication',{},'annonces')">${ic('megaphone',19)}${threadsFor().some(isUnread)?'<span class="dotn"></span>':''}</button>${ui.role==='admin'?`<button class="top-ic hide-sm" title="Paramètres" onclick="go('parametres')">${ic('settings',19)}</button>`:''}<div class="me">${esc(p.i)}</div></div></header>`}
P.megaphone='<path d="m3 11 18-5v12L3 14v-3z"/><path d="M11.6 16.8a3 3 0 1 1-5.8-1.6"/>';P.grad='<path d="M22 10 12 5 2 10l10 5 10-5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/>';P.pin='<path d="M12 17v5M9 10.8V4h6v6.8l3 3.2v2H6v-2z"/>';
function render(){CACHE={};const app=document.getElementById('app');const allowed=NAVS[ui.role].flatMap(s=>s[1].map(i=>i[0]));if(!allowed.includes(ui.page))ui.page='dashboard';let content;try{content=(VIEWS[ui.page]||VIEWS.dashboard)()}catch(e){console.error(e);content=`<div class="card empty">${ic('alert',28)}<div>Erreur d’affichage : ${esc(e.message)}</div></div>`}
 app.innerHTML=`<div class="layout">${sidebar()}<div class="scrim ${ui.sidebarOpen?'show':''}" onclick="toggleSidebar(false)"></div><main class="main">${topbar()}<div class="content">${content}</div></main></div>`;const cb=document.getElementById('conv-body');if(cb)cb.scrollTop=cb.scrollHeight}

/* ================= TABLEAUX DE BORD ================= */
const _dashAdmin=VIEWS.dashboard;
VIEWS.dashboard=function(){if(ui.role==='teacher')return dashTeacher();if(ui.role==='parent')return dashParent();
 const html=_dashAdmin();const st=students();const days=lastSchoolDays(TODAY,10);const rate=presenceRate(st,days);const todayAbs=S.attendance.filter(a=>a.date===TODAY&&a.status==='absent').length;const appel=isSchoolDay(TODAY)?S.classes.filter(c=>!S.appelDone[TODAY+'|'+c.id]):[];const g=avgOf(S.classes.filter(c=>graded(c.id)).map(c=>classGenAvg(c.id)));const newI=S.inscriptions.filter(i=>i.statut==='nouvelle').length;const up=S.events.filter(e=>e.date>=TODAY).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);
 const extra=`<div class="grid kpis mt">${kpi('Présence (10 jours)',pct(rate,1),`${todayAbs} absent${todayAbs>1?'s':''} aujourd’hui`,'checkCircle','t-emerald')}${kpi('Moyenne générale',fa(g),'1er trimestre · primaire et secondaire','edit','t-violet')}${kpi('Appels à faire',String(appel.length),appel.length?appel.slice(0,3).map(c=>c.name).join(', ')+(appel.length>3?'…':''):'Tous les appels sont faits','clock','t-amber')}${kpi('Demandes d’inscription',String(newI),'Nouvelles demandes 2027-2028','plus','t-sky')}</div>
 <div class="grid cols-2e mt"><div class="card"><div class="card-head"><h3>Prochains événements</h3><button class="link sm" onclick="go('edt',{},'cal')">Calendrier</button></div>${up.map(evItem).join('')||'<div class="empty">Aucun événement</div>'}</div><div class="card"><div class="card-head"><h3>Dernières annonces</h3><button class="link sm" onclick="go('communication',{},'annonces')">Tout voir</button></div>${S.announcements.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(a=>`<div class="list-item click" onclick="go('communication',{},'annonces')"><span class="ic-box t-sky">${ic('megaphone',15)}</span><div class="grow min0"><div class="fw5 ellipsis">${esc(a.title)}</div><div class="xs muted ellipsis">${esc(a.body)}</div></div><span class="xs muted">${fds(a.date)}</span></div>`).join('')}</div></div>`;
 const i=html.indexOf('<div class="grid cols-2 mt">');return i>0?html.slice(0,i)+extra+html.slice(i):html+extra};
const EVT={vacances:['Congés','#10b981'],conseil:['Conseil de classe','#6366f1'],reunion:['Réunion','#f59e0b'],finance:['Finances','#1f52e5'],vie:['Vie de l’école','#14b8a6'],examen:['Évaluations','#ef4444'],sortie:['Sortie','#ec4899']};
function evItem(e){const d=pd(e.date);return `<div class="list-item click" onclick="go('edt',{},'cal')"><div class="date-chip"><b>${d.getDate()}</b><span>${MO[d.getMonth()]}</span></div><div class="grow min0"><div class="fw5 ellipsis">${esc(e.title)}</div><div class="xs muted">${ucf(d.toLocaleDateString('fr-FR',{weekday:'long'}))} · ${EVT[e.type][0]}</div></div><span class="ev-dot" style="background:${EVT[e.type][1]}"></span></div>`}
function teacherLessons(day){const t=TEACHER_ID();const w=pd(day).getDay();return S.classes.flatMap(c=>(S.timetable[c.id]||[]).filter(l=>l.t===t&&l.d===w).map(l=>({...l,cid:c.id}))).sort((a,b)=>a.s-b.s)}
function dashTeacher(){const e=emp(TEACHER_ID());const mc=myClasses();const ms=mc.flatMap(c=>stuOfClass(c.id));const day=nextSchoolDay(TODAY),isT=day===TODAY;const L=teacherLessons(day);const todo=isT?[...new Set(L.map(l=>l.cid))].filter(c=>!S.appelDone[TODAY+'|'+c]):[];const un=threadsFor().filter(isUnread).length;const myE=S.evaluations.filter(v=>(S.assign[v.classId]||{})[v.subjectId]===e.id);
 return head('Accueil',`${ucf(new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}))} · ${L.length} cours ${isT?'aujourd’hui':'le '+pd(day).toLocaleDateString('fr-FR',{weekday:'long'})}`,`<button class="btn" onclick="go('notes')">${ic('edit',16)} Saisir des notes</button><button class="btn btn-primary" onclick="go('presences')">${ic('checkCircle',16)} Faire l’appel</button>`)+
 `<div class="grid kpis">${kpi('Mes élèves',String(ms.length),mc.length+' classes','users','t-sky')}${kpi('Cours '+(isT?'aujourd’hui':'à venir'),String(L.length),L.length?SLOTS[L[0].s]+' – '+SLOTE[L[L.length-1].s]:'Pas de cours','calendar','t-violet')}${kpi('Appels à faire',String(todo.length),isT?'Aujourd’hui':'Pas de cours aujourd’hui','checkCircle','t-amber')}${kpi('Messages non lus',String(un),'Parents d’élèves','send','t-rose')}</div>
 <div class="grid cols-2 mt"><div class="card"><div class="card-head"><h3>Mon programme ${isT?'du jour':'· '+pd(day).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</h3></div><div class="card-body">${L.map(l=>{const s=subj(l.sub),c=clsById(l.cid);const done=S.appelDone[TODAY+'|'+l.cid];return `<div class="tl"><div class="tl-time">${SLOTS[l.s]}<span>${SLOTE[l.s]}</span></div><div class="tl-card click" style="--c:${s.color}" onclick="go('classes',{classId:'${l.cid}'})"><div class="grow"><div class="fw6">${esc(s.name)} · ${esc(c.name)}</div><div class="xs muted">${esc(l.room)} · ${stuOfClass(l.cid).length} élèves</div></div>${isT?(done?badge('Appel fait','b-green'):`<button class="btn btn-xs btn-primary" onclick="event.stopPropagation();startAppel('${l.cid}')">Faire l’appel</button>`):''}</div></div>`}).join('')||'<div class="empty">Aucun cours</div>'}</div></div>
 <div class="card"><div class="card-head"><h3>Mes classes</h3></div>${mc.map(c=>{const subs=subjOf(c.id).filter(s=>S.assign[c.id][s.id]===e.id);const a=avgOf(subs.map(s=>classSubjAvg(c.id,s.id)));const weak=stuOfClass(c.id).filter(st=>{const v=avgOf(subs.map(s=>subjAvg(st,s.id)));return v!=null&&v<10}).length;return `<div class="list-item click" onclick="go('classes',{classId:'${c.id}'})"><div class="org-ini" style="width:38px;height:38px">${esc(c.name.replace(/\D/g,'')||c.name[0])}</div><div class="grow min0"><div class="fw5">${esc(c.name)}</div><div class="xs muted ellipsis">${subs.map(s=>s.short).join(' · ')} · ${weak} élève(s) sous 10</div></div>${avgCell(a)}</div>`}).join('')}</div></div>
 <div class="grid cols-2e mt"><div class="card"><div class="card-head"><h3>Messages des parents</h3><button class="link sm" onclick="go('communication')">Ouvrir</button></div>${threadsFor().slice(0,4).map(threadRow).join('')||'<div class="empty">Aucun message</div>'}</div><div class="card"><div class="card-head"><h3>Annonces</h3></div>${annFor().slice(0,3).map(a=>`<div class="list-item click" onclick="go('communication',{},'annonces')"><span class="ic-box t-sky">${ic('megaphone',15)}</span><div class="grow min0"><div class="fw5">${esc(a.title)}</div><div class="xs muted">${esc(a.body)}</div></div></div>`).join('')}</div></div>
 <div class="hint mt">${myE.length} évaluations saisies ce trimestre.</div>`}
function dashParent(){const k=curKid();const b=stuBal(k);const g=genAvg(k),rk=rankOf(k);const at=attOf(k.id);const ab=at.filter(a=>a.status==='absent');const next=stuInv(k.id).filter(i=>invStatus(i)!=='paid').sort((a,b)=>a.due.localeCompare(b.due))[0];
 const notes=S.evaluations.filter(e=>e.classId===k.level&&e.grades[k.id]!=null).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);const day=nextSchoolDay(TODAY);const L=(S.timetable[k.level]||[]).filter(l=>l.d===pd(day).getDay()).sort((a,b)=>a.s-b.s);
 return head('Accueil',esc(k.parent.name),'')+kidSwitch()+
 `<div class="grid kpis">${kpi('Moyenne générale',graded(k.level)?fa(g):'—',rk?'Rang '+rk[0]+' / '+rk[1]+' · classe '+fa(classGenAvg(k.level)):'Maternelle : pas de notes chiffrées','edit','t-violet')}${kpi('Absences',String(ab.length),ab.filter(a=>!a.justified).length+' non justifiée(s) · '+at.filter(a=>a.status==='retard').length+' retard(s)','checkCircle','t-amber')}${kpi('Reste à payer',`<span class="${b.late>0.5?'neg':''}">${money(b.rest)}</span>`,b.late>0.5?money(b.late)+' en retard':'Aucun retard','wallet','t-rose')}${kpi('Prochaine échéance',next?fds(next.due):'—',next?ucf(next.label||''):'Tout est réglé','calendar','t-sky')}</div>
 <div class="grid cols-2 mt"><div class="card"><div class="card-head"><h3>Dernières notes</h3><button class="link sm" onclick="go('notes')">Toutes les notes</button></div>${notes.map(e=>{const s=subj(e.subjectId),v=e.grades[k.id];const ca=avgOf(Object.values(e.grades));return `<div class="list-item click" onclick="go('notes')"><span class="ev-dot" style="background:${s.color}"></span><div class="grow min0"><div class="fw5">${esc(s.name)} · ${esc(e.title)}</div><div class="xs muted">${fds(e.date)} · moyenne de la classe ${fa(ca)}</div></div><b class="${v<10?'neg':''}">${String(v).replace('.',',')}<span class="muted fw5">/${e.max}</span></b></div>`}).join('')||'<div class="empty">Pas encore de notes</div>'}</div>
 <div class="card"><div class="card-head"><h3>${day===TODAY?'Aujourd’hui':ucf(pd(day).toLocaleDateString('fr-FR',{weekday:'long'}))}</h3><span class="xs muted">${esc(k.classe)}</span></div><div class="card-body">${L.map(l=>`<div class="tl"><div class="tl-time">${SLOTS[l.s]}<span>${SLOTE[l.s]}</span></div><div class="tl-card click" style="--c:${subj(l.sub).color}" onclick="go('edt')"><div><div class="fw5">${esc(subj(l.sub).name)}</div><div class="xs muted">${esc(tName(emp(l.t)))}</div></div></div></div>`).join('')||'<div class="empty">Pas de cours</div>'}</div></div></div>
 <div class="grid cols-2e mt"><div class="card"><div class="card-head"><h3>Annonces de l’école</h3></div>${annFor().slice(0,3).map(a=>`<div class="list-item click" onclick="go('communication',{},'annonces')"><span class="ic-box t-sky">${ic('megaphone',15)}</span><div class="grow min0"><div class="fw5">${esc(a.title)}</div><div class="xs muted">${esc(a.body)}</div></div></div>`).join('')}</div><div class="card"><div class="card-head"><h3>À venir</h3></div>${S.events.filter(e=>e.date>=TODAY).slice(0,4).map(evItem).join('')}</div></div>`}

/* ================= CLASSES & MATIÈRES ================= */
VIEWS.classes=function(){if(ui.params.classId)return classDetail(ui.params.classId);const list=ui.role==='teacher'?myClasses():S.classes;
 return head(ui.role==='teacher'?'Mes classes':'Classes & niveaux',`${list.length} classes · ${list.reduce((a,c)=>a+stuOfClass(c.id).length,0)} élèves`,ui.role==='admin'?`<button class="btn" onclick="go('edt')">${ic('calendar',16)} Emplois du temps</button>`:'')+
 `<div class="class-grid">${list.map(c=>{const ss=stuOfClass(c.id);const a=graded(c.id)?classGenAvg(c.id):null;const r=presenceRate(ss,lastSchoolDays(TODAY,10));return `<div class="ccard" onclick="go('classes',{classId:'${c.id}'})"><div class="ccard-top ${c.cycle}"><div class="tile"><div><b>${esc(shortCls(c.name))}</b><br><small>${esc(c.room)}</small></div></div></div><div class="ccard-body"><h4>${esc(c.name)}</h4><div class="meta">${ic('user',15)} ${esc(tName(emp(c.teacherId)))}</div><div class="meta">${ic('users',15)} ${ss.length} / ${c.capacity} élèves</div><div class="flex-between mt8"><span class="sm">Moyenne <b>${fa(a)}</b></span><span class="pillg">Présence ${pct(r,0)}</span></div><div class="progress mt8"><span style="width:${Math.min(100,ss.length/c.capacity*100)}%;background:${c.cycle==='Maternelle'?'#f59e0b':c.cycle==='Primaire'?'#10b981':'#1f52e5'}"></span></div></div></div>`}).join('')}</div>`};
const shortCls=n=>n.replace(/(\d)(re|e) maternelle/,'$1M').replace(/(\d)(re|e) primaire/,'$1P').replace('Humanités','H').replace(/^1re H\. (\w).*/,'1H$1').replace(/(\d)(re|e) H/,'$1H').replace(' EB','EB').replace('Petite section','PS').replace('Moyenne section','MS').replace('Grande section','GS');
function classDetail(cid){const c=clsById(cid);const ss=stuOfClass(cid);const days=lastSchoolDays(TODAY,10);const tab=ui.tab['cls']||'eleves';const g=graded(cid);
 let h=`<button class="link sm mb" onclick="go('classes')">${ic('chevronLeft',14)} ${ui.role==='teacher'?'Mes classes':'Toutes les classes'}</button>`+head(esc(c.name),`${c.cycle} · ${esc(c.room)} · titulaire : ${esc(tName(emp(c.teacherId)))}`,`<button class="btn" onclick="go('edt',{classId:'${cid}'})">${ic('calendar',16)} Emploi du temps</button>${g?`<button class="btn btn-primary" onclick="ui.f.notes={c:'${cid}'};go('notes')">${ic('edit',16)} Notes</button>`:''}`)+
 `<div class="grid kpis mb">${kpi('Effectif',ss.length+' / '+c.capacity,ss.filter(s=>s.sexe==='F').length+' filles · '+ss.filter(s=>s.sexe==='M').length+' garçons','users','t-sky')}${kpi('Moyenne de classe',g?fa(classGenAvg(cid)):'—',g?'1er trimestre':'Maternelle','edit','t-violet')}${kpi('Présence (10 jours)',pct(presenceRate(ss,days),1),'','checkCircle','t-emerald')}${kpi('Familles en retard',String(ss.filter(s=>stuBal(s).late>0.5).length),ui.role==='admin'?money(sum(ss.map(s=>stuBal(s).late)))+' échus':'Paiements','wallet','t-rose')}</div>`+
 `<div class="tabs">${[['eleves','Élèves'],['equipe','Équipe pédagogique']].map(([k,l])=>`<div class="tab ${k===tab?'active':''}" onclick="ui.tab.cls='${k}';render()">${l}</div>`).join('')}</div>`;
 if(tab==='equipe')return h+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Matière</th><th>Enseignant</th><th class="num">Heures / sem.</th><th class="num">Coef.</th><th class="num">Moyenne</th></tr></thead><tbody>${subjOf(cid).map(s=>`<tr><td><span class="ev-dot" style="background:${s.color}"></span> ${esc(s.name)}</td><td>${ui.role==='admin'?`<select class="input sm" style="max-width:260px" onchange="S.assign['${cid}']['${s.id}']=this.value;save();render();toast('Enseignant affecté')">${S.employees.filter(e=>/Prof|Institu|Maîtresse|Éducatrice|Préfet|Directeur/.test(e.poste)).map(e=>`<option value="${e.id}" ${S.assign[cid][s.id]===e.id?'selected':''}>${esc(tName(e))}</option>`).join('')}</select>`:esc(tName(teacherOf(cid,s.id)))}</td><td class="num">${(S.timetable[cid]||[]).filter(l=>l.sub===s.id).length} h</td><td class="num">${s.coef}</td><td class="num">${g?avgCell(classSubjAvg(cid,s.id)):'—'}</td></tr>`).join('')}</tbody></table></div></div>`;
 const rows=ss.map(s=>({s,a:g?genAvg(s):null,rk:g?rankOf(s):null,ab:attOf(s.id).filter(x=>x.status==='absent').length}));
 return h+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Élève</th><th class="num">Moyenne</th><th class="num hide-sm">Rang</th><th class="num">Absences</th><th class="hide-md">Parent</th>${ui.role==='admin'?'<th>Paiement</th>':''}</tr></thead><tbody>${rows.map(r=>{const b=stuBal(r.s);return `<tr class="click" onclick="${ui.role==='admin'?`openStudent('${r.s.id}')`:`openStudentEdu('${r.s.id}')`}"><td><div class="person">${avatar(r.s.name,30)}<div class="min0"><div class="n">${esc(r.s.name)}</div><div class="s">${r.s.matricule}</div></div></div></td><td class="num">${avgCell(r.a)}</td><td class="num hide-sm">${r.rk?r.rk[0]+'<span class="muted">/'+r.rk[1]+'</span>':'—'}</td><td class="num">${r.ab}</td><td class="hide-md sm">${esc(r.s.parent.name)}<div class="xs muted">${esc(r.s.parent.phone)}</div></td>${ui.role==='admin'?`<td>${b.late>0.5?badge('Retard','b-red'):badge('À jour','b-green')}</td>`:''}</tr>`}).join('')}</tbody></table></div></div>`}
function openStudentEdu(id){const s=client(id);const at=attOf(id);modal(esc(s.name),`<div class="flex mb" style="gap:14px">${avatar(s.name,52)}<div><div class="fw6" style="font-size:17px">${esc(s.name)}</div><div class="muted sm">${esc(s.classe)} · ${s.matricule}</div></div></div><div class="grid cols-2e"><dl class="dl"><div><dt>Moyenne générale</dt><dd>${fa(genAvg(s))}</dd></div><div><dt>Rang</dt><dd>${rankOf(s)?rankOf(s).join(' / '):'—'}</dd></div><div><dt>Absences</dt><dd>${at.filter(a=>a.status==='absent').length}</dd></div><div><dt>Retards</dt><dd>${at.filter(a=>a.status==='retard').length}</dd></div></dl><dl class="dl"><div><dt>Parent / tuteur</dt><dd>${esc(s.parent.name)}</dd></div><div><dt>Téléphone</dt><dd>${esc(s.parent.phone)}</dd></div></dl></div><div class="sec-title">Moyennes par matière</div>${hbars(subjOf(s.level).map(sb=>({label:sb.name,value:subjAvg(s,sb.id)||0,text:fa(subjAvg(s,sb.id))+' / 20',color:sb.color})),{max:20})}`,`<button class="btn" onclick="newThread('${id}')">${ic('send',16)} Écrire au parent</button>`,'wide')}
VIEWS.matieres=function(){return head('Matières',`${S.subjects.length} matières · coefficients et volumes horaires par cycle`,`<button class="btn btn-primary" onclick="openSubjectForm()">${ic('plus',16)} Ajouter une matière</button>`)+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Matière</th><th>Cycles</th><th class="num">Coefficient</th><th class="num">Heures / semaine</th><th class="hide-md">Enseignants</th><th class="num">Moyenne école</th><th></th></tr></thead><tbody>${S.subjects.map(s=>{const cls=S.classes.filter(c=>s.cycles.includes(c.cycle));const ts=[...new Set(cls.map(c=>S.assign[c.id][s.id]))].map(emp).filter(Boolean);const a=avgOf(cls.filter(c=>graded(c.id)).map(c=>classSubjAvg(c.id,s.id)));return `<tr><td><div class="flex"><span class="ic-box" style="background:${s.color}1a;color:${s.color};width:30px;height:30px;font-size:11px;font-weight:700">${esc(s.short)}</span><span class="fw5">${esc(s.name)}</span></div></td><td>${s.cycles.map(c=>badge(c,'b-gray',false)).join(' ')}</td><td class="num">${s.coef}</td><td class="num">${s.hours} h</td><td class="hide-md sm">${ts.slice(0,3).map(tName).join(', ')}${ts.length>3?' +'+(ts.length-3):''}</td><td class="num">${avgCell(a)}</td><td class="num"><button class="icon-btn" onclick="openSubjectForm('${s.id}')">${ic('edit',15)}</button></td></tr>`}).join('')}</tbody></table></div></div>`};
function openSubjectForm(id){const s=id?subj(id):{name:'',short:'',coef:1,hours:2,color:'#1f52e5',cycles:['Primaire']};const cyc=[...new Set(S.classes.map(c=>c.cycle))];modal(id?'Modifier la matière':'Nouvelle matière',`<div class="form-grid">${field('Nom','mf-n',s.name,{full:true})}${field('Abréviation','mf-s',s.short)}${field('Couleur','mf-c',s.color,{type:'color'})}${field('Coefficient','mf-k',s.coef,{type:'number'})}${field('Heures / semaine','mf-h',s.hours,{type:'number'})}<div class="field full"><label>Cycles</label>${cyc.map(c=>`<label class="check" style="display:inline-flex;margin-right:16px"><input type="checkbox" class="mf-cy" value="${c}" ${s.cycles.includes(c)?'checked':''}> ${c}</label>`).join('')}</div></div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="saveSubject('${id||''}')">Enregistrer</button>`)}
function saveSubject(id){const n=val('mf-n');if(!n){toast('Nom obligatoire','err');return}const cy=[...document.querySelectorAll('.mf-cy:checked')].map(x=>x.value);const o={id:id||uid('sb'),name:n,short:(val('mf-s')||n.slice(0,3)).toUpperCase(),color:val('mf-c'),coef:parseNum(val('mf-k'))||1,hours:parseNum(val('mf-h'))||1,cycles:cy.length?cy:['Primaire']};const ix=S.subjects.findIndex(s=>s.id===o.id);if(ix>=0)S.subjects[ix]=o;else S.subjects.push(o);for(const c of S.classes)if(o.cycles.includes(c.cycle)&&!S.assign[c.id][o.id])S.assign[c.id][o.id]=c.teacherId;save();closeModal();render();toast('Matière enregistrée')}

/* ================= EMPLOI DU TEMPS & CALENDRIER ================= */
VIEWS.edt=function(){const tab=tabOf('edt');const f=F();if(ui.params.classId){f.mode='c';f.c=ui.params.classId;ui.params={}}
 let h=head('Emploi du temps',`Semaine type · ${S.schoolYear}`,ui.role==='admin'&&tab==='cal'?`<button class="btn btn-primary" onclick="openEventForm()">${ic('plus',16)} Événement</button>`:'')+tabs([['edt','Emploi du temps'],['cal','Calendrier scolaire']],tab);
 if(tab==='cal')return h+calView();
 let lessons,mode;if(ui.role==='parent'){const k=curKid();h+=kidSwitch();lessons=S.timetable[k.level]||[];mode='c'}else if(ui.role==='teacher'&&f.mode!=='c'){mode='t';lessons=S.classes.flatMap(c=>(S.timetable[c.id]||[]).filter(l=>l.t===TEACHER_ID()).map(l=>({...l,cid:c.id})))}else{mode=f.mode||'c';if(mode==='t'){const tid=f.t||S.persona.teacher;lessons=S.classes.flatMap(c=>(S.timetable[c.id]||[]).filter(l=>l.t===tid).map(l=>({...l,cid:c.id})))}else{const cid=f.c&&clsById(f.c)?f.c:(ui.role==='teacher'?myClasses()[0].id:S.classes[0].id);f.c=cid;lessons=S.timetable[cid]||[]}}
 const teachers=S.employees.filter(e=>Object.values(S.assign).some(a=>Object.values(a).includes(e.id)));
 const bar=ui.role==='parent'?'':`<div class="toolbar">${ui.role==='admin'?`<div class="seg"><button class="${mode==='c'?'active':''}" onclick="setF('mode','c')">Par classe</button><button class="${mode==='t'?'active':''}" onclick="setF('mode','t')">Par enseignant</button></div>`:`<div class="seg"><button class="${mode==='t'?'active':''}" onclick="setF('mode','t')">Mon emploi du temps</button><button class="${mode==='c'?'active':''}" onclick="setF('mode','c')">Par classe</button></div>`}${mode==='c'?`<select class="input w-auto" onchange="setF('c',this.value)">${options((ui.role==='teacher'?myClasses():S.classes).map(c=>[c.id,c.name]),f.c)}</select>`:ui.role==='admin'?`<select class="input w-auto" onchange="setF('t',this.value)">${options(teachers.map(e=>[e.id,tName(e)]),f.t||S.persona.teacher)}</select>`:''}<span class="muted sm" style="margin-left:auto">${lessons.length} h / semaine</span></div>`;
 return h+`<div class="card">${bar}<div class="table-wrap"><div class="tt">${['',...WD].map(d=>`<div class="tt-h">${d}</div>`).join('')}${SLOTS.map((s,si)=>`${si===2?`<div class="tt-break">Récréation · 09:30 – 09:45</div>`:''}<div class="tt-time">${s}<span>${SLOTE[si]}</span></div>${[1,2,3,4,5].map(d=>{const l=lessons.find(x=>x.d===d&&x.s===si);if(!l)return '<div class="tt-cell"></div>';const sb=subj(l.sub);return `<div class="tt-cell"><div class="lesson" style="--c:${sb.color}"><b>${esc(sb.name)}</b><span>${mode==='t'?esc(clsById(l.cid).name):esc(tName(emp(l.t)))}</span><span>${esc(l.room)}</span></div></div>`}).join('')}`).join('')}</div></div></div>`};
function calView(){const m=ui.calMonth||TODAY.slice(0,7);const[y,mo]=m.split('-').map(Number);const first=new Date(y,mo-1,1);const off=(first.getDay()+6)%7;const n=new Date(y,mo,0).getDate();const cells=[];for(let i=0;i<off;i++)cells.push(null);for(let d=1;d<=n;d++)cells.push(m+'-'+pad(d));while(cells.length%7)cells.push(null);
 const up=S.events.filter(e=>e.date>=TODAY).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,7);
 return `<div class="grid cols-2"><div class="card"><div class="card-head"><div class="month-nav"><button class="icon-btn" onclick="ui.calMonth=prevMonth('${m}');render()">${ic('chevronLeft')}</button><b>${ucf(monthLabel(m))}</b><button class="icon-btn" onclick="ui.calMonth=nextMonth('${m}');render()">${ic('chevronRight')}</button></div><div class="legend" style="margin:0">${Object.values(EVT).slice(0,5).map(([l,c])=>`<span><i style="background:${c}"></i>${l}</span>`).join('')}</div></div><div class="cal">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(d=>`<div class="cal-h">${d}</div>`).join('')}${cells.map(d=>{if(!d)return '<div class="cal-c off"></div>';const ev=S.events.filter(e=>e.date===d);const hol=HOLI.some(([a,b])=>d>=a&&d<=b);return `<div class="cal-c ${d===TODAY?'today':''} ${hol?'hol':''}" ${ui.role==='admin'?`onclick="openEventForm('${d}')"`:''}><span class="cal-d">${+d.slice(8)}</span>${ev.map(e=>`<div class="cal-ev" style="--c:${EVT[e.type][1]}">${esc(e.title)}</div>`).join('')}</div>`}).join('')}</div></div><div class="card"><div class="card-head"><h3>À venir</h3></div>${up.map(evItem).join('')||'<div class="empty">Aucun événement</div>'}</div></div>`}
function openEventForm(d){modal('Nouvel événement',`<div class="form-grid">${field('Intitulé','evf-t','',{full:true,attrs:'placeholder="Ex. Sortie pédagogique au musée"'})}${field('Date','evf-d',d||TODAY,{type:'date'})}${selectF('Type','evf-y',Object.entries(EVT).map(([k,v])=>[k,v[0]]),'vie')}</div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="saveEvent()">Ajouter</button>`)}
function saveEvent(){const t=val('evf-t');if(!t){toast('Intitulé obligatoire','err');return}S.events.push({id:uid('ve'),title:t,date:val('evf-d')||TODAY,type:val('evf-y')});save();closeModal();render();toast('Événement ajouté au calendrier')}

/* ================= PRÉSENCES ================= */
function startAppel(cid){ui.appel=null;ui.tab.presences='appel';go('presences',{classId:cid})}
function initAppel(cid,date){const m={};stuOfClass(cid).forEach(s=>{const r=S.attendance.find(a=>a.date===date&&a.studentId===s.id);m[s.id]=r?(r.status==='absent'?'a':'r'):'p'});ui.appel={cid,date,m}}
VIEWS.presences=function(){if(ui.role==='parent')return parentAbs();const tab=tabOf('appel');let h=head(ui.role==='teacher'?'Appel':'Présences','Appel quotidien, absences, retards et justificatifs','')+tabs([['appel','Faire l’appel'],['suivi','Suivi des absences']],tab);
 if(tab==='suivi')return h+suiviAbs();const cls=ui.role==='teacher'?myClasses():S.classes;
 if(!ui.appel||(ui.params.classId&&ui.appel.cid!==ui.params.classId))initAppel(ui.params.classId||cls[0].id,ui.appel?ui.appel.date:TODAY);ui.params={};const A=ui.appel,ss=stuOfClass(A.cid);const done=S.appelDone[A.date+'|'+A.cid];const cnt=k=>Object.values(A.m).filter(x=>x===k).length;
 return h+`<div class="card"><div class="toolbar"><select class="input w-auto" onchange="initAppel(this.value,ui.appel.date);render()">${options(cls.map(c=>[c.id,c.name]),A.cid)}</select><input type="date" class="input w-auto" value="${A.date}" onchange="initAppel(ui.appel.cid,this.value);render()">${done?badge('Appel enregistré','b-green'):badge('Appel non effectué','b-amber')}${isSchoolDay(A.date)?'':badge('Jour sans cours','b-gray')}<span class="sm muted" style="margin-left:auto">${cnt('p')} présents · <span class="neg">${cnt('a')} absents</span> · ${cnt('r')} retards</span></div>
 ${ss.map(s=>`<div class="list-item"><div class="person grow">${avatar(s.name,34)}<div class="min0"><div class="n">${esc(s.name)}</div><div class="s">${s.matricule}</div></div></div><div class="seg att">${[['p','Présent'],['a','Absent'],['r','Retard']].map(([k,l])=>`<button class="${A.m[s.id]===k?'active '+k:''}" onclick="ui.appel.m['${s.id}']='${k}';render()">${l}</button>`).join('')}</div></div>`).join('')}
 <div class="table-foot"><button class="btn btn-sm" onclick="Object.keys(ui.appel.m).forEach(k=>ui.appel.m[k]='p');render()">Tous présents</button><button class="btn btn-primary" onclick="saveAppel()">${ic('check',16)} Enregistrer l’appel</button></div></div>`};
function saveAppel(){const A=ui.appel;const ids=new Set(stuOfClass(A.cid).map(s=>s.id));const keep=S.attendance.filter(a=>!(a.date===A.date&&ids.has(a.studentId)));let na=0,nr=0;for(const[sid,k]of Object.entries(A.m)){if(k==='p')continue;const old=S.attendance.find(a=>a.date===A.date&&a.studentId===sid&&(a.status==='absent')===(k==='a'));keep.push(old||{id:uid('at'),date:A.date,studentId:sid,status:k==='a'?'absent':'retard',justified:false,motif:'',minutes:k==='r'?10:0});k==='a'?na++:nr++}S.attendance=keep;S.appelDone[A.date+'|'+A.cid]=true;save();render();toast(`Appel enregistré : ${na} absent(s), ${nr} retard(s)`)}
function suiviAbs(){const f=F();if(!f.j)f.j='nj';const base=ui.role==='teacher'?new Set(myClasses().flatMap(c=>stuOfClass(c.id).map(s=>s.id))):null;let L=S.attendance.filter(a=>!base||base.has(a.studentId));if(f.c)L=L.filter(a=>client(a.studentId).level===f.c);if(f.t)L=L.filter(a=>a.status===f.t);if(f.j==='nj')L=L.filter(a=>!a.justified);if(f.j==='j')L=L.filter(a=>a.justified);L.sort((a,b)=>b.date.localeCompare(a.date));const lim=50*((ui.limit.presences||0)+1);const d30=lastSchoolDays(TODAY,20);const st=base?students().filter(s=>base.has(s.id)):students();
 return `<div class="grid kpis mb">${kpi('Taux de présence',pct(presenceRate(st,d30),1),'20 derniers jours de classe','checkCircle','t-emerald')}${kpi('Absences',String(S.attendance.filter(a=>a.status==='absent'&&(!base||base.has(a.studentId))).length),'Depuis la rentrée','alert','t-rose')}${kpi('Retards',String(S.attendance.filter(a=>a.status==='retard'&&(!base||base.has(a.studentId))).length),'Depuis la rentrée','clock','t-amber')}${kpi('Non justifiées',String(S.attendance.filter(a=>a.status==='absent'&&!a.justified&&(!base||base.has(a.studentId))).length),'À régulariser','file','t-violet')}</div>
 <div class="card"><div class="toolbar"><select class="input w-auto" onchange="setF('c',this.value)"><option value="">Toutes les classes</option>${options((ui.role==='teacher'?myClasses():S.classes).map(c=>[c.id,c.name]),f.c)}</select><select class="input w-auto" onchange="setF('t',this.value)"><option value="">Absences et retards</option>${options([['absent','Absences'],['retard','Retards']],f.t)}</select><div class="seg">${[['nj','Non justifiées'],['j','Justifiées'],['all','Toutes']].map(([k,l])=>`<button class="${f.j===k?'active':''}" onclick="setF('j','${k}')">${l}</button>`).join('')}</div></div>
 <div class="table-wrap"><table><thead><tr><th>Date</th><th>Élève</th><th class="hide-sm">Classe</th><th>Type</th><th class="hide-md">Motif</th><th></th></tr></thead><tbody>${L.slice(0,lim).map(a=>{const s=client(a.studentId);return `<tr><td class="sm">${fds(a.date)}</td><td><div class="person">${avatar(s.name,28)}<span class="n">${esc(s.name)}</span></div></td><td class="hide-sm">${esc(s.classe)}</td><td>${a.status==='absent'?badge('Absence','b-red'):badge('Retard'+(a.minutes?' '+a.minutes+' min':''),'b-amber')}</td><td class="hide-md sm">${a.justified?esc(a.motif||'Justifiée'):'<span class="muted">—</span>'}</td><td class="num">${a.justified?badge('Justifiée','b-green'):`<button class="btn btn-xs" onclick="openJustify('${a.id}')">Justifier</button>`}</td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">Aucune absence</div></td></tr>'}</tbody></table></div><div class="table-foot"><span>${L.length} ligne(s)</span>${L.length>lim?`<button class="btn btn-sm" onclick="more()">Afficher plus</button>`:''}</div></div>`}
function openJustify(id){modal('Justifier l’absence',`${selectF('Motif','jf-m',['Maladie','Rendez-vous médical','Raison familiale','Transport','Autre'].map(x=>[x,x]),'Maladie',{full:true})}${field('Commentaire','jf-c','',{full:true})}`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="const a=S.attendance.find(x=>x.id==='${id}');a.justified=true;a.motif=val('jf-m')+(val('jf-c')?' – '+val('jf-c'):'');save();closeModal();render();toast('Absence justifiée')">Valider</button>`)}
function parentAbs(){const k=curKid();const L=attOf(k.id);return head('Absences & retards',esc(k.name)+' · '+esc(k.classe),`<button class="btn btn-primary" onclick="openSignal()">${ic('plus',16)} Signaler une absence</button>`)+kidSwitch()+`<div class="grid kpis mb">${kpi('Absences',String(L.filter(a=>a.status==='absent').length),'Depuis la rentrée','alert','t-rose')}${kpi('Non justifiées',String(L.filter(a=>a.status==='absent'&&!a.justified).length),'À justifier','file','t-amber')}${kpi('Retards',String(L.filter(a=>a.status==='retard').length),'Depuis la rentrée','clock','t-violet')}${kpi('Présence',pct(presenceRate([k],lastSchoolDays(TODAY,40)),1),'40 derniers jours','checkCircle','t-emerald')}</div><div class="card">${L.map(a=>`<div class="list-item"><span class="ic-box ${a.status==='absent'?'t-rose':'t-amber'}">${ic(a.status==='absent'?'alert':'clock',15)}</span><div class="grow"><div class="fw5">${a.status==='absent'?'Absence':'Retard'} · ${ucf(pd(a.date).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}))}</div><div class="xs muted">${a.justified?esc(a.motif||'Justifiée'):'Non justifiée'}</div></div>${a.justified?badge('Justifiée','b-green'):`<button class="btn btn-xs" onclick="openJustify('${a.id}')">Justifier</button>`}</div>`).join('')||'<div class="empty">Aucune absence enregistrée</div>'}</div>`}
function openSignal(){modal('Signaler une absence',`<div class="form-grid">${field('Date','sg-d',TODAY,{type:'date'})}${selectF('Motif','sg-m',['Maladie','Rendez-vous médical','Raison familiale','Autre'].map(x=>[x,x]),'Maladie')}${field('Précisions','sg-c','',{full:true})}</div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="S.attendance.push({id:uid('at'),date:val('sg-d'),studentId:curKid().id,status:'absent',justified:true,motif:'Signalée par la famille – '+val('sg-m')+(val('sg-c')?' : '+val('sg-c'):'')});save();closeModal();render();toast('Absence signalée à l’école')">Envoyer</button>`)}

/* ================= NOTES & ÉVALUATIONS ================= */
function notePairs(){const t=ui.role==='teacher'?TEACHER_ID():null;const out=[];for(const c of S.classes){if(!graded(c.id))continue;for(const s of subjOf(c.id))if(!t||S.assign[c.id][s.id]===t)out.push([c.id,s.id])}return out}
VIEWS.notes=function(){if(ui.role==='parent')return parentNotes();const tab=tabOf('saisie');const f=F();const pairs=notePairs();const cls=[...new Set(pairs.map(p=>p[0]))];if(!cls.includes(f.c))f.c=cls[0];const subs=pairs.filter(p=>p[0]===f.c).map(p=>p[1]);if(!subs.includes(f.s))f.s=subs[0];
 let h=head('Notes & évaluations',`1er trimestre ${S.schoolYear} · notes sur 20`,tab==='saisie'?`<button class="btn btn-primary" onclick="openEvalForm()">${ic('plus',16)} Nouvelle évaluation</button>`:'')+tabs([['saisie','Saisie des notes'],['moy','Moyennes de classe']],tab);
 const bar=`<div class="toolbar"><select class="input w-auto" onchange="setF('c',this.value)">${options(cls.map(c=>[c,clsById(c).name]),f.c)}</select>${tab==='saisie'?`<select class="input w-auto" onchange="setF('s',this.value)">${options(subs.map(s=>[s,subj(s).name]),f.s)}</select>`:''}<span class="sm muted" style="margin-left:auto">Moyenne de classe : <b>${fa(tab==='saisie'?classSubjAvg(f.c,f.s):classGenAvg(f.c))}</b></span></div>`;
 const ss=stuOfClass(f.c);
 if(tab==='moy'){const sb=subjOf(f.c);const rows=ss.map(s=>({s,g:genAvg(s)})).sort((a,b)=>(b.g??-1)-(a.g??-1));return h+`<div class="card">${bar}<div class="table-wrap"><table><thead><tr><th>Rang</th><th>Élève</th>${sb.map(s=>`<th class="num" title="${esc(s.name)}">${s.short}<div class="xs subtle">×${s.coef}</div></th>`).join('')}<th class="num">Moyenne</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="fw6">${r.g!=null?i+1:'—'}</td><td class="fw5" style="white-space:nowrap">${esc(r.s.name)}</td>${sb.map(s=>`<td class="num">${avgCell(subjAvg(r.s,s.id))}</td>`).join('')}<td class="num fw6">${avgCell(r.g)}</td></tr>`).join('')}</tbody><tfoot><tr><td></td><td>Moyenne de classe</td>${sb.map(s=>`<td class="num">${fa(classSubjAvg(f.c,s.id))}</td>`).join('')}<td class="num">${fa(classGenAvg(f.c))}</td></tr></tfoot></table></div></div>`}
 const ev=evalsOf(f.c,f.s);
 return h+`<div class="card">${bar}<div class="table-wrap"><table class="grades"><thead><tr><th class="sticky">Élève</th>${ev.map(e=>`<th class="num click" onclick="openEvalForm('${e.id}')" title="Modifier l’évaluation"><div class="fw5" style="color:var(--text)">${esc(e.title)}</div><div class="xs subtle">${fds(e.date).slice(0,5)} · /${e.max} · ×${e.coef}</div></th>`).join('')}<th class="num">Moyenne</th></tr></thead><tbody>${ss.map((s,ri)=>`<tr><td class="sticky fw5" style="white-space:nowrap">${esc(s.name)}</td>${ev.map((e,ci)=>`<td class="num"><input class="var-in grade" data-r="${ri}" data-c="${ci}" value="${e.grades[s.id]!=null?String(e.grades[s.id]).replace('.',','):''}" placeholder="—" onchange="setGrade('${e.id}','${s.id}',this)" onkeydown="gradeKey(event,this)"></td>`).join('')}<td class="num fw6" id="sa-${s.id}">${avgCell(subjAvg(s,f.s))}</td></tr>`).join('')}</tbody><tfoot><tr><td class="sticky">Moyenne de l’évaluation</td>${ev.map(e=>`<td class="num" id="ea-${e.id}">${fa(avgOf(Object.values(e.grades)))}</td>`).join('')}<td class="num">${fa(classSubjAvg(f.c,f.s))}</td></tr></tfoot></table></div>${ev.length?'':'<div class="empty">Aucune évaluation : créez-en une pour saisir des notes.</div>'}<div class="table-foot"><span>Saisie enregistrée automatiquement · Entrée pour passer à l’élève suivant</span><span>${teacherOf(f.c,f.s)?esc(tName(teacherOf(f.c,f.s))):''}</span></div></div>`};
function setGrade(eid,sid,el){const e=S.evaluations.find(x=>x.id===eid);const v=el.value.trim();if(v===''){delete e.grades[sid]}else{const n=parseNum(v);if(isNaN(n)||n<0||n>e.max){el.classList.add('err');toast('Note invalide (0 à '+e.max+')','err');return}e.grades[sid]=n}el.classList.remove('err');save();const s=client(sid);const c1=document.getElementById('sa-'+sid);if(c1)c1.innerHTML=avgCell(subjAvg(s,e.subjectId));const c2=document.getElementById('ea-'+eid);if(c2)c2.textContent=fa(avgOf(Object.values(e.grades)))}
function gradeKey(ev,el){if(ev.key==='Enter'){ev.preventDefault();const n=document.querySelector(`.grade[data-r="${+el.dataset.r+1}"][data-c="${el.dataset.c}"]`);el.blur();if(n){n.focus();n.select()}}}
function openEvalForm(id){const e=id?S.evaluations.find(x=>x.id===id):null;modal(e?'Modifier l’évaluation':'Nouvelle évaluation',`<div class="form-grid">${field('Intitulé','ef-t',e?e.title:'',{full:true,attrs:'placeholder="Ex. Contrôle de géométrie"'})}${field('Date','ef-d',e?e.date:TODAY,{type:'date'})}${selectF('Coefficient','ef-k',[[1,'×1'],[2,'×2'],[3,'×3']],e?e.coef:1)}${selectF('Noté sur','ef-m',[[10,'10'],[20,'20'],[40,'40'],[100,'100']],e?e.max:20)}</div>`,`${e?`<button class="btn btn-danger" style="margin-right:auto" onclick="S.evaluations=S.evaluations.filter(x=>x.id!=='${id}');save();closeModal();render();toast('Évaluation supprimée')">Supprimer</button>`:''}<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="saveEval('${id||''}')">Enregistrer</button>`)}
function saveEval(id){const t=val('ef-t');if(!t){toast('Intitulé obligatoire','err');return}const f=F();if(id){Object.assign(S.evaluations.find(x=>x.id===id),{title:t,date:val('ef-d'),coef:+val('ef-k'),max:+val('ef-m')})}else S.evaluations.push({id:uid('ev'),classId:f.c,subjectId:f.s,title:t,date:val('ef-d')||TODAY,coef:+val('ef-k'),max:+val('ef-m'),term:1,grades:{}});save();closeModal();render();toast('Évaluation enregistrée')}
function parentNotes(){const k=curKid();const tab=tabOf('notes');let h=head('Notes & bulletins',esc(k.name)+' · '+esc(k.classe),'')+kidSwitch();if(!graded(k.level))return h+`<div class="card empty">${ic('grad',28)}<div>En maternelle, l’évaluation se fait par compétences, sans notes chiffrées.</div></div>`;h+=tabs([['notes','Dernières notes'],['moy','Moyennes'],['bul','Bulletin']],tab);
 if(tab==='bul')return h+(S.published[k.level]?bulletinHTML(k,false):`<div class="card empty">${ic('file',28)}<div class="fw5" style="color:var(--text)">Bulletin du 1er trimestre</div><div>Il sera disponible après le conseil de classe.</div></div>`);
 if(tab==='moy')return h+`<div class="card"><div class="card-body">${subjOf(k.level).map(s=>{const a=subjAvg(k,s.id),c=classSubjAvg(k.level,s.id);return `<div class="mb"><div class="flex-between sm"><span class="fw5">${esc(s.name)} <span class="muted xs">×${s.coef}</span></span><span>${avgCell(a)} <span class="muted xs">classe ${fa(c)}</span></span></div><div class="dual"><span style="width:${(a||0)/20*100}%;background:${s.color}"></span><i style="left:${(c||0)/20*100}%"></i></div></div>`}).join('')}<div class="hr"></div><div class="flex-between"><b>Moyenne générale</b><b>${fa(genAvg(k))} / 20</b></div></div></div>`;
 const ev=S.evaluations.filter(e=>e.classId===k.level&&e.grades[k.id]!=null).sort((a,b)=>b.date.localeCompare(a.date));return h+`<div class="card">${ev.map(e=>{const s=subj(e.subjectId),v=e.grades[k.id];return `<div class="list-item"><span class="ic-box" style="background:${s.color}1a;color:${s.color};font-size:11px;font-weight:700">${s.short}</span><div class="grow min0"><div class="fw5">${esc(s.name)} · ${esc(e.title)}</div><div class="xs muted">${fds(e.date)} · coef ${e.coef} · moyenne de la classe ${fa(avgOf(Object.values(e.grades)))}</div></div><b class="${v/e.max<.5?'neg':''}">${String(v).replace('.',',')}<span class="muted fw5">/${e.max}</span></b></div>`}).join('')}</div>`}

/* ================= BULLETINS ================= */
function bulletinHTML(s,edit){const c=clsById(s.level),co=S.company;const g=genAvg(s),rk=rankOf(s);const at=attOf(s.id);const ab=at.filter(a=>a.status==='absent');const pp=emp(c.teacherId);const gen=S.appr[s.id+'|gen']||autoAppr(g);const me=mention(g);
 const rows=subjOf(c.id).map(sb=>{const a=subjAvg(s,sb.id);const vals=stuOfClass(c.id).map(x=>subjAvg(x,sb.id)).filter(x=>x!=null);const t=teacherOf(c.id,sb.id);const ap=S.appr[s.id+'|'+sb.id]||autoAppr(a);const canE=edit&&(ui.role==='admin'||(t&&t.id===TEACHER_ID()));return `<tr><td><div class="fw5">${esc(sb.name)}</div><div class="xs muted">${esc(tName(t))} · coef ${sb.coef}</div></td><td class="num fw6">${fa(a)}</td><td class="num muted">${fa(avgOf(vals))}</td><td class="num muted hide-sm">${vals.length?fa(Math.min(...vals))+' / '+fa(Math.max(...vals)):'—'}</td><td class="${canE?'editable':''}" ${canE?`onclick="editAppr('${s.id}','${sb.id}')"`:''}>${esc(ap)}</td></tr>`}).join('');
 return `<div class="paper bulletin"><div class="paper-head"><div class="flex" style="gap:12px"><div class="logo-sq" style="width:42px;height:42px">${orgIni()}</div><div><div class="co">${esc(co.name)}</div>${co.motto?`<div class="motto">${esc(co.motto)}</div>`:''}<div class="xs muted">${esc(co.address)}, ${esc(co.city)} · ${esc(co.phone)}</div></div></div><div style="text-align:right"><div class="doc-title">BULLETIN SCOLAIRE</div><div class="sm">1er trimestre · ${S.schoolYear}</div></div></div>
 <div class="blocks"><div class="block"><h5>Élève</h5><b>${esc(s.name)}</b><div class="xs">Matricule ${s.matricule} · ${s.sexe==='F'?'Fille':'Garçon'}</div></div><div class="block"><h5>Classe</h5><b>${esc(c.name)}</b><div class="xs">Titulaire : ${esc(tName(pp))} · effectif ${stuOfClass(c.id).length}</div></div></div>
 <div class="table-wrap"><table><thead><tr><th>Matière</th><th class="num">Moyenne</th><th class="num">Moy. classe</th><th class="num hide-sm">Min / Max</th><th>Appréciation</th></tr></thead><tbody>${rows}</tbody></table></div>
 <div class="bul-foot"><div class="bul-box"><div class="xs muted">Moyenne générale</div><div class="bul-big">${fa(g)}<span>/20</span></div><div class="xs muted">Rang ${rk?rk[0]+' / '+rk[1]:'—'} · classe ${fa(classGenAvg(c.id))}</div></div><div class="bul-box"><div class="xs muted">Vie scolaire</div><div class="sm">${ab.length} absence(s) dont ${ab.filter(a=>!a.justified).length} non justifiée(s)</div><div class="sm">${at.filter(a=>a.status==='retard').length} retard(s)</div></div><div class="bul-box grow ${edit&&ui.role==='admin'?'editable':''}" ${edit&&ui.role==='admin'?`onclick="editAppr('${s.id}','gen')"`:''}><div class="xs muted">Appréciation du conseil de classe</div><div class="sm">${esc(gen)}</div>${me?`<span class="badge b-indigo mt8">${me}</span>`:''}</div></div>
 <div class="sign"><div>Le titulaire<br><b>${esc(tName(pp))}</b></div><div>La direction<br><b>${esc(co.director)}</b></div></div></div>`}
VIEWS.bulletins=function(){const f=F();const cls=(ui.role==='teacher'?myClasses():S.classes).filter(c=>graded(c.id));if(!cls.some(c=>c.id===f.c))f.c=(cls.find(c=>stuOfClass(c.id).length)||cls[0]||{}).id;const ss=stuOfClass(f.c);if(!ss.length)return head('Bulletins',S.schoolYear,'')+`<div class="card empty">${ic('file',28)}<div>Aucun élève inscrit pour l’instant. Les bulletins apparaîtront dès que des élèves et des notes seront saisis.</div></div>`;if(!ss.some(s=>s.id===f.s))f.s=ss[0].id;const i=ss.findIndex(s=>s.id===f.s);const pub=S.published[f.c];
 return head('Bulletins',`1er trimestre ${S.schoolYear} · cliquez sur une appréciation pour la modifier`,ui.role==='admin'?`<button class="btn" onclick="copyText(document.querySelector('.content .paper').innerText,'Bulletin copié')">${ic('copy',16)} Copier</button><button class="btn ${pub?'':'btn-primary'}" onclick="S.published['${f.c}']=!S.published['${f.c}'];save();render();toast(S.published['${f.c}']?'Bulletins publiés dans l’espace parents':'Publication retirée')">${ic(pub?'check':'send',16)} ${pub?'Publiés aux parents':'Publier aux parents'}</button>`:'')+
 `<div class="card mb"><div class="toolbar" style="border-bottom:0"><select class="input w-auto" onchange="setF('c',this.value)">${options(cls.map(c=>[c.id,c.name]),f.c)}</select><button class="icon-btn" ${i<=0?'disabled':''} onclick="setF('s','${(ss[i-1]||{}).id}')">${ic('chevronLeft')}</button><select class="input w-auto" onchange="setF('s',this.value)">${options(ss.map(s=>[s.id,s.name]),f.s)}</select><button class="icon-btn" ${i>=ss.length-1?'disabled':''} onclick="setF('s','${(ss[i+1]||{}).id}')">${ic('chevronRight')}</button><span class="sm muted" style="margin-left:auto">${i+1} / ${ss.length}</span>${pub?badge('Visible par les parents','b-green'):badge('Non publié','b-gray')}</div></div>${bulletinHTML(client(f.s),true)}`};
function editAppr(sid,key){const cur=S.appr[sid+'|'+key]||(key==='gen'?autoAppr(genAvg(client(sid))):autoAppr(subjAvg(client(sid),key)));modal('Appréciation'+(key==='gen'?' générale':' – '+subj(key).name),`<textarea class="input" rows="4" id="ap-t">${esc(cur)}</textarea>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="S.appr['${sid}|${key}']=val('ap-t');save();closeModal();render();toast('Appréciation enregistrée')">Enregistrer</button>`)}

/* ================= INSCRIPTIONS ================= */
const IST={nouvelle:['Nouvelles demandes','b-indigo'],en_cours:['Dossier en cours','b-amber'],validee:['Validées','b-green'],refusee:['Refusées','b-gray']};
const IDOCS={acte:'Acte de naissance',photo:'Photos d’identité',bulletin:'Derniers bulletins',domicile:'Justificatif de domicile'};
VIEWS.inscriptions=function(){const tab=tabOf('dem');let h=head('Inscriptions',`Admissions et réinscriptions · rentrée 2027-2028`,tab==='dem'?`<button class="btn btn-primary" onclick="openInscForm()">${ic('plus',16)} Nouvelle demande</button>`:`<button class="btn" onclick="relanceReinsc()">${ic('send',16)} Relancer les familles</button>`)+tabs([['dem','Demandes d’admission',S.inscriptions.length],['re','Réinscriptions']],tab);
 if(tab==='re'){const st=students();const c={oui:0,non:0,attente:0};st.forEach(s=>c[S.reinsc[s.id]||'attente']++);const f=F();let L=st.slice();if(f.c)L=L.filter(s=>s.level===f.c);if(f.r)L=L.filter(s=>(S.reinsc[s.id]||'attente')===f.r);const lim=50*((ui.limit.inscriptions||0)+1);
  return h+`<div class="grid kpis mb">${kpi('Réinscrits',String(c.oui),pct(c.oui/st.length,0)+' des élèves','checkCircle','t-emerald')}${kpi('En attente de réponse',String(c.attente),'À relancer','clock','t-amber')}${kpi('Départs annoncés',String(c.non),'Ne se réinscrivent pas','alert','t-rose')}${kpi('Places à pourvoir',String(Math.max(0,sum(S.classes.map(x=>x.capacity))-c.oui-S.inscriptions.filter(i=>i.statut==='validee').length)),'Prévision 2027-2028','users','t-sky')}</div>
  <div class="card"><div class="toolbar"><select class="input w-auto" onchange="setF('c',this.value)"><option value="">Toutes les classes</option>${options(S.classes.map(x=>[x.id,x.name]),f.c)}</select><div class="seg">${[['','Tous'],['attente','En attente'],['oui','Réinscrits'],['non','Départs']].map(([k,l])=>`<button class="${(f.r||'')===k?'active':''}" onclick="setF('r','${k}')">${l}</button>`).join('')}</div></div><div class="table-wrap"><table><thead><tr><th>Élève</th><th>Classe actuelle</th><th class="hide-md">Parent</th><th>Réinscription 2027-2028</th></tr></thead><tbody>${L.slice(0,lim).map(s=>`<tr><td><div class="person">${avatar(s.name,28)}<span class="n">${esc(s.name)}</span></div></td><td>${esc(s.classe)}</td><td class="hide-md sm">${esc(s.parent.name)}</td><td><select class="input sm w-auto" onchange="S.reinsc['${s.id}']=this.value;save();render()">${options([['attente','En attente'],['oui','Réinscrit'],['non','Ne revient pas']],S.reinsc[s.id]||'attente')}</select></td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>${L.length} élève(s)</span>${L.length>lim?`<button class="btn btn-sm" onclick="more()">Afficher plus</button>`:''}</div></div>`}
 return h+`<div class="kanban">${Object.keys(IST).map(k=>{const L=S.inscriptions.filter(i=>i.statut===k);return `<div class="kcol"><div class="kcol-head">${badge(IST[k][0],IST[k][1])}<span class="muted sm">${L.length}</span></div>${L.map(i=>{const d=Object.values(i.docs),ok=d.filter(Boolean).length;return `<div class="kcard" onclick="openInsc('${i.id}')"><div class="person">${avatar(i.prenom+' '+i.nom,32)}<div class="min0"><div class="n">${esc(i.prenom+' '+i.nom)}</div><div class="s">${esc((S.fees.find(l=>l.id===i.level)||{}).name)} · ${i.annee}</div></div></div><div class="kmeta"><span>${ic('file',13)} ${ok}/${d.length} pièces</span><span>${fds(i.date)}</span></div><div class="progress"><span style="width:${ok/d.length*100}%"></span></div></div>`}).join('')||'<div class="kempty">Aucune demande</div>'}</div>`}).join('')}</div>`};
function openInsc(id){const i=S.inscriptions.find(x=>x.id===id);const lv=S.fees.find(l=>l.id===i.level)||{};let act='';if(i.statut==='nouvelle')act=`<button class="btn btn-primary" onclick="setInsc('${id}','en_cours')">Étudier le dossier</button>`;else if(i.statut==='en_cours')act=`<button class="btn btn-danger" onclick="setInsc('${id}','refusee')">Refuser</button><button class="btn btn-primary" onclick="setInsc('${id}','validee')">Valider l’admission</button>`;else act=`<button class="btn" onclick="setInsc('${id}','en_cours')">Rouvrir</button>`;
 modal('Demande d’admission',`<div class="flex mb">${avatar(i.prenom+' '+i.nom,48)}<div class="grow"><div class="fw6" style="font-size:17px">${esc(i.prenom+' '+i.nom)}</div><div class="sm muted">${esc(lv.name)} · ${i.annee} · reçue le ${fd(i.date)}</div></div>${badge(...IST[i.statut])}</div><dl class="dl"><div><dt>Parent / tuteur</dt><dd>${esc(i.parent.name)}</dd></div><div><dt>Téléphone</dt><dd>${esc(i.parent.phone)}</dd></div><div><dt>Origine</dt><dd>${esc(i.source)}</dd></div><div><dt>Frais annuels</dt><dd>${money((lv.scol||0)+(lv.insc||0))}</dd></div>${i.note?`<div><dt>Note</dt><dd>${esc(i.note)}</dd></div>`:''}</dl><div class="sec-title">Pièces du dossier</div>${Object.entries(IDOCS).map(([k,l])=>`<label class="check" style="padding:6px 0"><input type="checkbox" ${i.docs[k]?'checked':''} onchange="S.inscriptions.find(x=>x.id==='${id}').docs.${k}=this.checked;save();render()"> ${l}</label>`).join('')}${i.statut==='en_cours'&&i.annee===S.schoolYear?`<div class="note mt">${ic('info',16)}<div>Arrivée en cours d’année : la validation crée l’élève et son échéance de rentrée.</div></div>`:''}`,act)}
function setInsc(id,st){const i=S.inscriptions.find(x=>x.id===id);i.statut=st;if(st==='validee'&&i.annee===S.schoolYear&&!i.studentId){const lv=S.fees.find(l=>l.id===i.level);const s={id:uid('el'),type:'eleve',prenom:i.prenom,nom:i.nom,name:i.prenom+' '+i.nom.toUpperCase(),sexe:i.sexe,level:lv.id,classe:lv.name,cycle:lv.cycle,matricule:(S.country==='CD'?'CSE-':'GSE-')+String(26000+S.clients.length+1),nouveau:true,cantine:false,transport:false,parent:{civ:'',name:i.parent.name,phone:i.parent.phone,mm:country().mm[0]},country:S.company.country,city:S.company.city,currency:S.currency,terms:15,email:'',birth:''};S.clients.push(s);S.seq.inv++;S.invoices.push({id:uid('iv'),num:'F-'+TODAY.slice(0,4)+'-'+String(S.seq.inv).padStart(5,'0'),clientId:s.id,date:TODAY,due:addDays(TODAY,15),currency:S.currency,rate:1,lines:feeLines(s,{n:1,sy:S.schoolYear,pct:S.tranches[0]}),status:'sent',notes:'',label:'1re tranche '+S.schoolYear,sy:S.schoolYear,tranche:1});i.studentId=s.id}save();render();openInsc(id);toast(st==='validee'?'Admission validée':st==='refusee'?'Demande refusée':'Statut mis à jour')}
function openInscForm(){modal('Nouvelle demande d’admission',`<div class="form-grid">${field('Prénom','if-p','')}${field('Nom','if-n','')}${selectF('Sexe','if-s',[['F','Fille'],['M','Garçon']],'F')}${selectF('Classe demandée','if-l',S.fees.map(l=>[l.id,l.name]),S.fees[0].id)}${selectF('Année','if-a',[['2027-2028','2027-2028'],[S.schoolYear,S.schoolYear+' (en cours d’année)']],'2027-2028')}${selectF('Origine','if-o',['Site web','Portes ouvertes','Recommandation','Téléphone','Visite'].map(x=>[x,x]),'Visite')}${field('Parent / tuteur','if-pn','',{attrs:'placeholder="Ex. Mme Sarah Kabeya"'})}${field('Téléphone','if-pt','')}</div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="saveInsc()">Enregistrer</button>`)}
function saveInsc(){if(!val('if-p')||!val('if-n')){toast('Prénom et nom obligatoires','err');return}S.inscriptions.unshift({id:uid('in'),prenom:val('if-p'),nom:val('if-n'),sexe:val('if-s'),level:val('if-l'),annee:val('if-a'),statut:'nouvelle',date:TODAY,source:val('if-o'),parent:{name:val('if-pn')||'—',phone:val('if-pt')},docs:{acte:false,photo:false,bulletin:false,domicile:false},note:''});save();closeModal();render();toast('Demande enregistrée')}
function relanceReinsc(){const L=students().filter(s=>(S.reinsc[s.id]||'attente')==='attente');const txt=`Bonjour, la campagne de réinscription 2027-2028 du ${S.company.name} est ouverte. Merci de confirmer la réinscription de votre enfant avant le 15 février auprès du secrétariat ou par retour de message.`;modal('Relancer les familles',`<p class="sm muted" style="margin-top:0">${L.length} familles n’ont pas encore répondu. Message à envoyer :</p><textarea class="input" rows="4" id="msg">${esc(txt)}</textarea><div class="sec-title">Numéros (${L.length})</div><textarea class="input" rows="5" id="nums">${esc(L.map(s=>s.parent.phone+' – '+s.parent.name+' ('+s.name+')').join('\n'))}</textarea>`,`<button class="btn" onclick="copyText(val('nums'),'Numéros copiés')">${ic('copy',16)} Copier les numéros</button><button class="btn btn-primary" onclick="copyText(val('msg'),'Message copié')">${ic('copy',16)} Copier le message</button>`)}

/* ================= COMMUNICATION ================= */
function annFor(){const r=ui.role;return S.announcements.filter(a=>r==='admin'||a.audience==='tous'||(r==='teacher'&&a.audience==='enseignants')||(r==='parent'&&(a.audience==='parents'||(a.audience.startsWith('classe:')&&kids().some(k=>k.level===a.audience.slice(7)))))||(r==='teacher'&&a.audience.startsWith('classe:')&&myClasses().some(c=>c.id===a.audience.slice(7)))).sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||b.date.localeCompare(a.date))}
const AUD=a=>a==='tous'?'Toute l’école':a==='parents'?'Parents':a==='enseignants'?'Enseignants':'Parents – '+(clsById(a.slice(7))||{}).name;
function thTitle(t){const s=client(t.studentId);return ui.role==='parent'?(t.with==='admin'?'Administration':tName(emp(t.with))):s.parent.name}
function thSub(t){const s=client(t.studentId);return ui.role==='parent'?s.prenom+' · '+s.classe:'Parent de '+s.name+' · '+s.classe}
const relD=d=>{const day=d.slice(0,10);return day===TODAY?d.slice(11):day===addDays(TODAY,-1)?'Hier':fds(day).slice(0,5)};
function threadRow(t){const last=t.messages[t.messages.length-1];return `<div class="list-item click ${isUnread(t)?'unread':''}" onclick="openThread('${t.id}')">${avatar(thTitle(t),36)}<div class="grow min0"><div class="flex-between"><span class="fw5 ellipsis">${esc(thTitle(t))}</span><span class="xs muted">${relD(last.date)}</span></div><div class="sm ellipsis">${esc(t.subject)}</div><div class="xs muted ellipsis">${esc(last.text)}</div></div>${isUnread(t)?'<span class="udot"></span>':''}</div>`}
function openThread(id){const t=S.threads.find(x=>x.id===id);if(ui.role==='parent')t.unread.parent=false;else t.unread.staff=false;save();go('communication',{thread:id},'msg')}
VIEWS.communication=function(){const tab=tabOf('msg');const canPost=ui.role!=='parent';let h=head('Communication',ui.role==='parent'?'Échangez avec l’école et les enseignants':'Messagerie avec les familles et annonces',tab==='msg'?`<button class="btn btn-primary" onclick="newThread()">${ic('plus',16)} Nouveau message</button>`:canPost?`<button class="btn btn-primary" onclick="openAnnForm()">${ic('megaphone',16)} Publier une annonce</button>`:'')+tabs([['msg','Messagerie',threadsFor().filter(isUnread).length||''],['annonces','Annonces']],tab);
 if(tab==='annonces')return h+`<div class="ann-list">${annFor().map(a=>`<div class="card ann"><div class="card-body"><div class="flex-between wrap"><div class="flex">${a.pinned?`<span class="ic-box t-amber">${ic('pin',15)}</span>`:`<span class="ic-box t-sky">${ic('megaphone',15)}</span>`}<div><div class="fw6">${esc(a.title)}</div><div class="xs muted">${esc(a.author)} · ${fd(a.date)}</div></div></div>${badge(AUD(a.audience),'b-gray',false)}</div><p class="sm" style="margin:12px 0 0;color:var(--text2)">${esc(a.body)}</p>${canPost?`<div class="flex mt"><a class="btn btn-sm" target="_blank" rel="noopener" style="text-decoration:none" href="https://wa.me/?text=${encodeURIComponent(a.title+' — '+a.body+' ('+S.company.name+')')}">${ic('send',14)} Partager sur WhatsApp</a><button class="btn btn-sm" onclick="copyText(${esc(JSON.stringify(a.title+'\n'+a.body))},'Annonce copiée')">${ic('copy',14)} Copier</button></div>`:''}</div></div>`).join('')}</div>`;
 const L=threadsFor().slice().sort((a,b)=>b.messages[b.messages.length-1].date.localeCompare(a.messages[a.messages.length-1].date));const cur=ui.params.thread?S.threads.find(t=>t.id===ui.params.thread):null;
 return h+`<div class="card msg ${cur?'has':''}"><div class="threads">${L.map(t=>`<div class="${cur&&cur.id===t.id?'th-active':''}">${threadRow(t)}</div>`).join('')||'<div class="empty">Aucune conversation</div>'}</div><div class="conv">${cur?`<div class="conv-head"><button class="icon-btn back" onclick="go('communication')">${ic('chevronLeft')}</button>${avatar(thTitle(cur),36)}<div class="min0"><div class="fw6 ellipsis">${esc(cur.subject)}</div><div class="xs muted ellipsis">${esc(thTitle(cur))} · ${esc(thSub(cur))}</div></div>${ui.role!=='parent'?`<a class="btn btn-sm hide-sm" style="margin-left:auto;text-decoration:none" target="_blank" rel="noopener" href="${waLink(client(cur.studentId).parent.phone,'')}">WhatsApp</a>`:''}</div><div class="conv-body" id="conv-body">${cur.messages.map(m=>{const mine=(ui.role==='parent')===(m.from==='parent');return `<div class="bub-row ${mine?'mine':''}"><div class="bub">${esc(m.text)}<div class="bub-meta">${m.from==='parent'?esc(client(cur.studentId).parent.name):(cur.with==='admin'?'Administration':esc(tName(emp(cur.with))))} · ${relD(m.date)}</div></div></div>`}).join('')}</div><div class="conv-reply"><textarea id="reply" class="input" rows="2" placeholder="Écrire une réponse…"></textarea><button class="btn btn-primary" onclick="sendReply('${cur.id}')">${ic('send',16)}</button></div>`:`<div class="empty" style="margin:auto">${ic('send',28)}<div>Sélectionnez une conversation</div></div>`}</div></div>`};
function sendReply(id){const t=S.threads.find(x=>x.id===id);const v=val('reply');if(!v)return;const d=new Date();t.messages.push({from:ui.role==='parent'?'parent':'staff',text:v,date:TODAY+' '+pad(d.getHours())+':'+pad(d.getMinutes())});if(ui.role==='parent')t.unread.staff=true;else t.unread.parent=true;save();render();toast('Message envoyé')}
function newThread(sid){let who='';if(ui.role==='parent'){const k=curKid();const ts=[...new Set(Object.values(S.assign[k.level]||{}))].map(emp).filter(Boolean);who=`${selectF('Enfant','nt-s',kids().map(c=>[c.id,c.prenom+' · '+c.classe]),k.id)}${selectF('Destinataire','nt-w',[['admin','Administration'],...ts.map(e=>[e.id,tName(e)])],'admin')}`}else{const L=ui.role==='teacher'?myClasses().flatMap(c=>stuOfClass(c.id)):students();who=selectF('Parent de l’élève','nt-s',L.map(s=>[s.id,s.classe+' · '+s.name+' ('+s.parent.name+')']),sid||L[0].id,{full:true})}
 modal('Nouveau message',`<div class="form-grid">${who}${field('Objet','nt-o','',{full:true})}${areaF('Message','nt-m','',{rows:5})}</div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="saveThread()">${ic('send',16)} Envoyer</button>`)}
function saveThread(){const m=val('nt-m');if(!m){toast('Message vide','err');return}const d=new Date();const t={id:uid('th'),studentId:val('nt-s'),with:ui.role==='parent'?val('nt-w'):ui.role==='teacher'?TEACHER_ID():'admin',subject:val('nt-o')||'Sans objet',unread:{staff:ui.role==='parent',parent:ui.role!=='parent'},messages:[{from:ui.role==='parent'?'parent':'staff',text:m,date:TODAY+' '+pad(d.getHours())+':'+pad(d.getMinutes())}]};S.threads.push(t);save();closeModal();go('communication',{thread:t.id},'msg');toast('Message envoyé')}
function openAnnForm(){const aud=ui.role==='admin'?[['tous','Toute l’école'],['parents','Tous les parents'],['enseignants','Enseignants'],...S.classes.map(c=>['classe:'+c.id,'Parents – '+c.name])]:myClasses().map(c=>['classe:'+c.id,'Parents – '+c.name]);modal('Publier une annonce',`<div class="form-grid">${field('Titre','af-t','',{full:true})}${areaF('Message','af-b','',{rows:5})}${selectF('Destinataires','af-a',aud,aud[0][0],{full:true})}<label class="check field full"><input type="checkbox" id="af-p"> Épingler en haut</label></div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="saveAnn()">Publier</button>`)}
function saveAnn(){if(!val('af-t')||!val('af-b')){toast('Titre et message obligatoires','err');return}S.announcements.unshift({id:uid('an'),title:val('af-t'),body:val('af-b'),audience:val('af-a'),date:TODAY,author:persona().n,pinned:document.getElementById('af-p').checked});save();closeModal();render();toast('Annonce publiée')}

/* ================= DOCUMENTS ================= */
const DOCS=[{id:'certif',name:'Certificat de scolarité',desc:'Atteste l’inscription de l’élève pour l’année en cours.',icon:'grad',c:'t-sky'},{id:'attest',name:'Attestation de paiement',desc:'Récapitulatif des frais réglés (employeur, bourse…).',icon:'wallet',c:'t-emerald'},{id:'bulletin',name:'Bulletin scolaire',desc:'Bulletin du trimestre avec moyennes et appréciations.',icon:'file',c:'t-violet'},{id:'fiche',name:'Fiche de renseignements',desc:'Informations administratives et contacts.',icon:'user',c:'t-amber'},{id:'liste',name:'Liste de classe',desc:'Liste nominative des élèves d’une classe.',icon:'users',c:'t-rose',scope:'class'}];
VIEWS.documents=function(){const par=ui.role==='parent';const list=par?DOCS.filter(d=>d.id!=='liste'&&d.id!=='fiche'):DOCS;
 return head('Documents',par?'Téléchargez les documents de vos enfants':'Génération des documents administratifs','')+(par?kidSwitch():'')+`<div class="class-grid mb">${list.map(d=>`<div class="card doc-card" onclick="${par?`openDoc('${d.id}','${curKid().id}')`:`docPicker('${d.id}')`}"><div class="card-body"><span class="ic-box ${d.c}">${ic(d.icon,18)}</span><div class="fw6 mt">${d.name}</div><div class="sm muted">${d.desc}</div><div class="link sm mt8">${par?'Ouvrir':'Générer'} ${ic('chevronRight',13)}</div></div></div>`).join('')}</div>`+(par?'':`<div class="card"><div class="card-head"><h3>Derniers documents édités</h3></div>${S.docLog.slice(-8).reverse().map(l=>`<div class="list-item click" onclick="openDoc('${l.type}','${l.ref}')"><span class="ic-box t-gray">${ic('file',15)}</span><div class="grow"><div class="fw5">${DOCS.find(d=>d.id===l.type).name}</div><div class="xs muted">${esc(l.label)} · ${fd(l.date)}</div></div>${ic('chevronRight',16)}</div>`).join('')||'<div class="empty">Aucun document édité pour le moment</div>'}</div>`)};
function docPicker(type){const d=DOCS.find(x=>x.id===type);const opts=d.scope==='class'?S.classes.map(c=>[c.id,c.name]):students().slice().sort((a,b)=>S.fees.findIndex(x=>x.id===a.level)-S.fees.findIndex(x=>x.id===b.level)||a.name.localeCompare(b.name)).map(s=>[s.id,s.classe+' · '+s.name]);modal(d.name,selectF(d.scope==='class'?'Classe':'Élève','dp-r',opts,opts[0][0],{full:true}),`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="openDoc('${type}',val('dp-r'),true)">Générer</button>`)}
function openDoc(type,ref,log){const co=S.company;const d=DOCS.find(x=>x.id===type);let body='',label='';const today=new Date().toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});
 const hd=t=>`<div class="paper-head"><div class="flex" style="gap:12px"><div class="logo-sq" style="width:42px;height:42px">${orgIni()}</div><div><div class="co">${esc(co.name)}</div>${co.motto?`<div class="motto">${esc(co.motto)}</div>`:''}<div class="xs muted">${esc(co.address)}, ${esc(co.city)} · ${esc(co.phone)}<br>${esc(co.rc)}</div></div></div><div class="doc-title">${t}</div></div>`;
 const sign=`<div class="sign"><div></div><div>Fait à ${esc(co.city)}, le ${today}<br><br><b>${esc(co.director)}</b><br>Direction</div></div>`;
 if(type==='liste'){const c=clsById(ref);label=c.name;body=`<div class="paper">${hd('LISTE DE CLASSE')}<p><b>${esc(c.name)}</b> · ${S.schoolYear} · titulaire ${esc(tName(emp(c.teacherId)))}</p><table><thead><tr><th>#</th><th>Nom et prénom</th><th>Matricule</th><th>Sexe</th><th>Parent</th><th>Téléphone</th></tr></thead><tbody>${stuOfClass(ref).map((s,i)=>`<tr><td>${i+1}</td><td>${esc(s.nom.toUpperCase()+' '+s.prenom)}</td><td>${s.matricule}</td><td>${s.sexe}</td><td>${esc(s.parent.name)}</td><td>${esc(s.parent.phone)}</td></tr>`).join('')}</tbody></table></div>`}
 else{const s=client(ref);label=s.name;
  if(type==='bulletin'){if(!graded(s.level)){toast('Pas de bulletin chiffré en maternelle','err');return}body=bulletinHTML(s,false)}
  else if(type==='certif')body=`<div class="paper">${hd('CERTIFICAT DE SCOLARITÉ')}<p style="margin-top:28px;line-height:2">Je soussignée, <b>${esc(co.director)}</b>, directrice du <b>${esc(co.name)}</b>, certifie que l’élève <b>${esc(s.name)}</b>, matricule ${s.matricule}, est régulièrement inscrit${s.sexe==='F'?'e':''} dans notre établissement en classe de <b>${esc(s.classe)}</b> pour l’année scolaire <b>${S.schoolYear}</b>.</p><p style="line-height:2">Ce certificat est délivré pour servir et valoir ce que de droit.</p>${sign}</div>`;
  else if(type==='attest'){const P=S.txs.filter(t=>t.match&&t.match.t==='inv'&&invById(t.match.id).clientId===s.id&&invById(t.match.id).sy===S.schoolYear);const tot=sum(P.map(t=>t.amount));body=`<div class="paper">${hd('ATTESTATION DE PAIEMENT')}<p style="margin-top:24px;line-height:1.9">Nous attestons avoir reçu de <b>${esc(s.parent.name)}</b> la somme de <b>${money(tot)}</b> (${amountWords(tot).toLowerCase()}) au titre des frais de scolarité de <b>${esc(s.name)}</b>, classe de ${esc(s.classe)}, pour l’année ${S.schoolYear}.</p><table><thead><tr><th>Reçu</th><th>Date</th><th>Objet</th><th class="num">Montant</th></tr></thead><tbody>${P.map(t=>`<tr><td>${t.ref}</td><td>${fds(t.date)}</td><td>${esc(invById(t.match.id).label)}</td><td class="num">${money(t.amount)}</td></tr>`).join('')}</tbody></table><div class="totals"><div class="big"><span>Total réglé</span><span>${money(tot)}</span></div></div>${sign}</div>`}
  else body=`<div class="paper">${hd('FICHE DE RENSEIGNEMENTS')}<div class="blocks"><div class="block"><h5>Élève</h5><b>${esc(s.name)}</b><div class="xs">${s.matricule} · ${s.sexe==='F'?'Fille':'Garçon'} · ${esc(s.classe)}</div></div><div class="block"><h5>Responsable</h5><b>${esc(s.parent.name)}</b><div class="xs">${esc(s.parent.phone)} · ${esc(s.parent.mm||'')}</div></div></div><dl class="dl"><div><dt>Bibliothèque numérique</dt><dd>${s.cantine?'Oui':'Non'}</dd></div><div><dt>Transport scolaire</dt><dd>${s.transport?'Oui':'Non'}</dd></div><div><dt>Nouvel élève</dt><dd>${s.nouveau?'Oui':'Non'}</dd></div><div><dt>Frais annuels</dt><dd>${money(annualFee(s))}</dd></div></dl>${sign}</div>`}
 if(log){S.docLog.push({type,ref,label,date:TODAY});save()}modal(d.name+' – '+esc(label),body,`<button class="btn" onclick="copyText(document.querySelector('.modal .paper').innerText,'Texte copié')">${ic('copy',16)} Copier le texte</button>`,'wide');if(log)render()}

/* ================= PAIEMENTS (PARENT) ================= */
VIEWS.paiements=function(){const k=curKid();const b=stuBal(k);const inv=stuInv(k.id).slice().sort((a,b)=>b.date.localeCompare(a.date));const P=S.txs.filter(t=>t.match&&t.match.t==='inv'&&invById(t.match.id).clientId===k.id).sort((a,b)=>b.date.localeCompare(a.date));const open=inv.filter(i=>invStatus(i)!=='paid').sort((a,b)=>a.due.localeCompare(b.due))[0];
 return head('Paiements',esc(k.name)+' · '+esc(k.classe),open?`<button class="btn btn-primary" onclick="payInfo('${open.id}')">${ic('phone',16)} Payer par Mobile Money</button>`:'')+kidSwitch()+`<div class="grid kpis mb">${kpi('Frais de l’année',mshort(annualFee(k)),S.schoolYear,'receipt','t-sky',money(annualFee(k)))}${kpi('Déjà réglé',mshort(b.paid),P.length+' paiement(s)','checkCircle','t-emerald',money(b.paid))}${kpi('Reste à payer',`<span class="${b.late>0.5?'neg':''}">${mshort(b.rest)}</span>`,b.late>0.5?money(b.late)+' en retard':'À jour','wallet','t-rose',money(b.rest))}${kpi('Prochaine échéance',open?fds(open.due):'—',open?ucf(open.label||''):'Tout est réglé','calendar','t-amber')}</div>
 <div class="grid cols-2e"><div class="card"><div class="card-head"><h3>Échéances</h3></div>${inv.map(i=>`<div class="list-item click" onclick="openInvoice('${i.id}')"><div class="grow min0"><div class="fw5">${esc(ucf(i.label||i.num))}</div><div class="xs muted">avant le ${fds(i.due)} · ${money(invPaid(i))} réglé sur ${money(invTtcLocal(i))}</div></div>${badge(...INV_ST[invStatus(i)])}</div>`).join('')}</div><div class="card"><div class="card-head"><h3>Reçus</h3></div>${P.map(t=>`<div class="list-item click" onclick="openReceipt('${t.id}')"><span class="ic-box t-emerald">${ic('file',15)}</span><div class="grow"><div class="fw5">${t.ref}</div><div class="xs muted">${fds(t.date)} · ${MODE_LBL(t.tid)}</div></div><b class="pos">${money(t.amount)}</b></div>`).join('')||'<div class="empty">Aucun paiement</div>'}</div></div>`};
function payInfo(iid){const i=invById(iid),s=client(i.clientId);const rem=rnd(invTtcLocal(i)-invPaid(i));modal('Payer par Mobile Money',`<div class="rc-amount" style="margin-top:0;padding:16px 18px;border-radius:14px;background:#f3f6ff;border:1px dashed #c9d5fb"><div class="xs muted">Montant à payer</div><div style="font-size:26px;font-weight:700;color:var(--primary)">${money(rem)}</div><div class="sm">${esc(ucf(i.label))} · ${esc(s.name)}</div></div><dl class="dl mt"><div><dt>Numéro marchand de l’école</dt><dd>${esc(S.company.mobile)}</dd></div><div><dt>Référence à indiquer</dt><dd><b>${s.matricule}</b></dd></div></dl><p class="sm muted">Après votre paiement, l’économat le rapproche et votre reçu apparaît dans « Reçus ». Vous pouvez aussi payer à la caisse de l’école ou par virement (${esc(S.company.bank)}).</p>`,`<button class="btn" onclick="copyText('${s.matricule}','Référence copiée')">${ic('copy',16)} Copier la référence</button><button class="btn btn-primary" onclick="closeModal()">J’ai compris</button>`)}

/* ================= RAPPORTS ================= */
VIEWS.rapports=function(){const st=students();const graded_=S.classes.filter(c=>graded(c.id));const d20=lastSchoolDays(TODAY,20);const inv=syInv();const fact=sum(inv.map(invTtcLocal)),paid=sum(inv.map(invPaid));
 const rows=S.classes.map(c=>{const ss=stuOfClass(c.id);let dd=0,pp=0;for(const s of ss)for(const i of stuInv(s.id).filter(i=>i.sy===S.schoolYear)){dd+=invTtcLocal(i);pp+=invPaid(i)}return{c,n:ss.length,f:ss.filter(s=>s.sexe==='F').length,moy:graded(c.id)?classGenAvg(c.id):null,pres:presenceRate(ss,d20),rec:dd?pp/dd:null,reste:dd-pp}});
 const cell=(v,txt,warn)=>`<td class="num"><div class="rbar"><span style="width:${Math.round((v||0)*100)}%" class="${warn?'w':''}"></span></div><span class="${warn?'neg':''}">${txt}</span></td>`;
 return head('Rapports',`Année scolaire ${S.schoolYear} · chiffres arrêtés au ${fds(TODAY)}`,`<button class="btn" onclick="copyReport()">${ic('copy',16)} Copier pour Excel</button>`)+
 `<div class="grid kpis mb">${kpi('Élèves inscrits',String(st.length),st.filter(s=>s.sexe==='F').length+' filles · '+st.filter(s=>s.sexe==='M').length+' garçons')}${kpi('Moyenne générale',fa(avgOf(graded_.map(c=>classGenAvg(c.id)))),'1er trimestre, primaire et secondaire')}${kpi('Présence',pct(presenceRate(st,d20),1),'Sur les 20 derniers jours de classe')}${kpi('Recouvrement',pct(fact?paid/fact:0,0),money(paid)+' encaissés sur '+money(fact))}</div>
 <div class="card"><div class="card-head"><h3>Par classe</h3><span class="xs muted">Cliquez sur une classe pour l’ouvrir</span></div><div class="table-wrap"><table><thead><tr><th>Classe</th><th class="num">Élèves</th><th class="num">Moyenne</th><th class="num">Présence</th><th class="num">Frais payés</th><th class="num hide-sm">Reste dû</th></tr></thead><tbody>${rows.map(r=>`<tr class="click" onclick="go('classes',{classId:'${r.c.id}'})"><td class="fw5">${esc(r.c.name)}</td><td class="num">${r.n}<span class="xs muted"> · ${r.f} F</span></td><td class="num ${r.moy!=null&&r.moy<10?'neg':''}">${r.moy==null?'<span class="muted">—</span>':fa(r.moy)}</td>${cell(r.pres,pct(r.pres,1),r.pres<.9)}${r.rec==null?'<td class="num muted">—</td>':cell(r.rec,pct(r.rec,0),r.rec<.6)}<td class="num hide-sm">${money(r.reste)}</td></tr>`).join('')}</tbody><tfoot><tr><td>Total</td><td class="num">${st.length}</td><td class="num">${fa(avgOf(graded_.map(c=>classGenAvg(c.id))))}</td><td class="num">${pct(presenceRate(st,d20),1)}</td><td class="num">${pct(fact?paid/fact:0,0)}</td><td class="num hide-sm">${money(fact-paid)}</td></tr></tfoot></table></div></div>`};
function copyReport(){const d20=lastSchoolDays(TODAY,20);const rows=['Classe;Effectif;Filles;Moyenne;Présence 20j;Facturé;Encaissé'];for(const c of S.classes){const ss=stuOfClass(c.id);let dd=0,pp=0;for(const s of ss)for(const i of stuInv(s.id).filter(i=>i.sy===S.schoolYear)){dd+=invTtcLocal(i);pp+=invPaid(i)}rows.push([c.name,ss.length,ss.filter(s=>s.sexe==='F').length,fa(graded(c.id)?classGenAvg(c.id):null),pct(presenceRate(ss,d20),1),nfmt(dd),nfmt(pp)].join(';'))}copyText(rows.join('\n'),'Rapport copié — collez-le dans Excel')}

/* ---------- vues partagées : version parent ---------- */
const _openInvoice=openInvoice;openInvoice=function(id,kind){if(ui.role!=='parent')return _openInvoice(id,kind);const d=S.invoices.find(x=>x.id===id);modal('Facture '+d.num,`<div class="flex mb">${badge(...INV_ST[invStatus(d)])}<span class="sm muted">Réglé : <b>${money(invPaid(d))}</b> · reste : <b>${money(Math.max(0,invTtcLocal(d)-invPaid(d)))}</b></span></div>`+docPaper(d,'inv'),`${invStatus(d)!=='paid'?`<button class="btn btn-primary" onclick="payInfo('${id}')">${ic('phone',16)} Payer par Mobile Money</button>`:''}`,'wide')};
const _openReceipt=openReceipt;openReceipt=function(id){if(ui.role!=='parent')return _openReceipt(id);const t=S.txs.find(x=>x.id===id);modal('Reçu '+t.ref,receiptHTML(t),`<button class="btn" onclick="copyText(document.querySelector('.modal .paper').innerText,'Reçu copié')">${ic('copy',16)} Copier</button>`,'wide')};
